insert into public.questoes (numero, parte, capitulo, pergunta, resposta, status)
values
  (631, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Tem meios o homem de distinguir por si mesmo o que é bem do que é mal?', 'Sim, quando crê em Deus e o quer saber. Deus lhe deu a inteligência para distinguir um do outro.', 'rascunho'),
  (632, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Estando sujeito ao erro, não pode o homem enganar-se na apreciação do bem e do mal e crer que pratica o bem quando em realidade pratica o mal?', 'Jesus disse: vede o que queríeis que vos fizessem ou não vos fizessem. Tudo se resume nisso. Não vos enganareis.', 'rascunho'),
  (633, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'A regra do bem e do mal, que se poderia chamar de reciprocidade ou de solidariedade, é inaplicável ao proceder pessoal do homem para consigo mesmo. Achará ele, na lei natural, a regra desse proceder e um guia seguro? 214 – Allan Kar dec', 'Quando comeis em excesso, verificais que isso vos faz mal. Pois bem, é Deus quem vos dá a medida daquilo de que necessitais. Quando excedeis dessa medida, sois punidos. Em tudo é assim. A lei natural traça para o homem o limite das suas necessidades. Se ele ultrapassa esse limite, é punido pelo sofrimento. Se atendesse sempre à voz que lhe diz — basta, evitaria a maior parte dos males, cuja culpa lança à Natureza.', 'rascunho'),
  (634, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Por que está o mal na natureza das coisas? Falo do mal moral. Não podia Deus ter criado a Humanidade em melhores condições?', 'Já te dissemos: os Espíritos foram criados simples e ignorantes. Deus deixa que o homem escolha o caminho. Tanto pior para ele, se toma o caminho mau: mais longa será sua peregrinação. Se não existissem montanhas, não compreenderia o homem que se pode subir e descer; se não existissem rochas, não compreenderia que há corpos duros. É preciso que o Espírito ganhe experiência; é preciso, portanto, que conheça o bem e o mal. Eis por que se une ao corpo.', 'rascunho'),
  (635, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Das diferentes posições sociais nascem necessidades que não são idênticas para todos os homens. Não parece poder inferir-se daí que a lei natural não constitui regra uniforme?', 'Essas diferentes posições são da natureza das coisas e conformes à lei do progresso. Isso não infirma a unidade da lei natural, que se aplica a tudo." As condições de existência do homem mudam de acordo com os tempos e os lugares, do que lhe resultam necessidades diferentes e posições sociais apropriadas a essas necessidades. Pois que está na ordem das coisas, tal diversidade é conforme à lei de Deus, lei que não deixa de ser una quanto ao seu princípio. À razão cabe distinguir as necessidades reais das factícias ou convencionais.', 'rascunho'),
  (636, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'São absolutos, para todos os homens, o bem e o mal?', 'A lei de Deus é a mesma para todos; porém, o mal depende principalmente da vontade que se tenha de o praticar. O bem é sempre o bem e o mal sempre o mal, qualquer que seja a posição do homem. Diferença só há quanto ao grau da responsabilidade.', 'rascunho'),
  (637, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Será culpado o selvagem que, cedendo ao seu instinto, se nutre de carne humana?', 'Eu disse que o mal depende da vontade. Pois bem! Tanto mais culpado é o homem, quanto melhor sabe o que faz." As circunstâncias dão relativa gravidade ao bem e ao mal. Muitas vezes, comete o homem faltas, que, nem por serem conseqüência da posição em que a sociedade o colocou, se tornam menos repreensíveis. Mas, a sua responsabilidade é proporcionada aos meios de que ele dispõe para compreender o bem e o mal. Assim, mais culpado é, aos olhos de Deus, o homem instruído que pratica uma simples injustiça, do que o selvagem ignorante que se entrega aos seus instintos.', 'rascunho'),
  (638, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Parece, às vezes, que o mal é uma conseqüência da força das coisas. Tal, por exemplo, a necessidade em que o homem se vê, nalguns casos, de destruir, até mesmo o seu semelhante. Poder-se-á dizer que há, então, infração da lei de Deus?', 'Embora necessário, o mal não deixa de ser o mal. Essa necessidade desaparece, entretanto, à medida que a alma se depura, passando de uma a outra existência. Então, mais culpado é o homem, quando o pratica, porque melhor o compreende.', 'rascunho'),
  (639, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Não sucede freqüentemente resultar o mal, que o homem pratica, da posição em que os outros homens o colocam? Quais, nesse caso, os culpados?', 'O mal recai sobre quem lhe foi o causador. Nessas condições, aquele que é levado a praticar o mal pela posição em que seus semelhantes o colocam tem menos culpa do que os que, assim procedendo, o ocasionaram. Porque, cada um será punido, não só pelo mal que haja feito, mas também pelo mal a que tenha dado lugar.', 'rascunho'),
  (640, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Aquele que não pratica o mal, mas que se aproveita do mal praticado por outrem, é tão culpado quanto este?', 'É como se o houvera praticado. Aproveitar do mal é participar dele. Talvez não fosse capaz de praticá-lo; mas, desde que, achando-o feito, dele tira partido, é que o aprova; é que o teria praticado, se pudera, ou se ousara.', 'rascunho'),
  (641, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Será tão repreensível, quanto fazer o mal, o desejá-lo?', 'Conforme. Há virtude em resistir-se voluntariamente ao mal que se deseja praticar, sobretudo quando há possibilidade de satisfazer-se a esse desejo. Se apenas não o pratica por falta de ocasião, é culpado quem o deseja.', 'rascunho'),
  (642, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Para agradar a Deus e assegurar a sua posição futura, bastará que o homem não pratique o mal?', 'Não; cumpre-lhe fazer o bem no limite de suas forças, porquanto responderá por todo mal que haja resultado de não haver praticado o bem.', 'rascunho'),
  (643, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Haverá quem, pela sua posição, não tenha possibilidade de fazer o bem?', 'Não há quem não possa fazer o bem. Somente o egoísta nunca encontra ensejo de o praticar. Basta que se esteja em relações com outros homens para que se tenha ocasião de fazer o bem, e não há dia da existência que não ofereça, a quem não se ache cego pelo egoísmo, oportunidade de praticá-lo. Porque, fazer o bem não consiste, para o homem, apenas em ser caridoso, mas em ser útil, na medida do possível, todas as vezes que o seu concurso venha a ser necessário.', 'rascunho'),
  (644, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Para certos homens, o meio onde se acham colocados não representa a causa primária de muitos vícios e crimes?', 'Sim, mas ainda aí há uma prova que o Espírito escolheu, quando em liberdade, levado pelo desejo de expor-se à tentação para ter o mérito da resistência.', 'rascunho'),
  (645, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Quando o homem se acha, de certo modo, mergulhado na atmosfera do vício, o mal não se lhe torna um arrastamento quase irresistível? 216 – Allan Kar dec', 'Arrastamento, sim; irresistível, não; porquanto, mesmo dentro da atmosfera do vício, com grandes virtudes às vezes deparas. São Espíritos que tiveram a força de resistir e que, ao mesmo tempo, receberam a missão de exercer boa influência sobre os seus semelhantes.', 'rascunho'),
  (646, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Estará subordinado a determinadas condições o mérito do bem que se pratique? Por outra: será de diferentes graus o mérito que resulta da prática do bem?', 'O mérito do bem está na dificuldade em praticá-lo. Nenhum merecimento há em fazê-lo sem esforço e quando nada custe. Em melhor conta tem Deus o pobre que divide com outro o seu único pedaço de pão, do que o rico que apenas dá do que lhe sobra, disse-o Jesus, a propósito do óbolo da viúva.', 'rascunho'),
  (647, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'A lei de Deus se acha contida toda no preceito do amor ao próximo, ensinado por Jesus?', 'Certamente esse preceito encerra todos os deveres dos homens uns para com os outros. Cumpre, porém, se lhes mostre a aplicação que comporta, do contrário deixarão de cumpri-lo, como o fazem presentemente. Demais, a lei natural abrange todas as circunstâncias da vida e esse preceito compreende só uma parte da lei. Aos homens são necessárias regras precisas; os preceitos gerais e muito vagos deixam grande número de portas abertas à interpretação.', 'rascunho'),
  (648, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Que pensais da divisão da lei natural em dez partes, compreendendo as leis de adoração, trabalho, reprodução, conservação, destruição, sociedade, progresso, igualdade, liberdade e, por fim, a de justiça, amor e caridade?', 'Essa divisão da lei de Deus em dez partes é a de Moisés e de natureza a abranger todas as circunstâncias da vida, o que é essencial. Podes, pois, adotá-la, sem que, por isso, tenha qualquer coisa de absoluta, como não o tem nenhum dos outros sistemas de classificação, que todos dependem do prisma pelo qual se considere o que quer que seja. A última lei é a mais importante, por ser a que faculta ao homem adiantar-se mais na vida espiritual, visto que resume todas as outras.', 'rascunho'),
  (649, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Em que consiste a adoração?', 'Na elevação do pensamento a Deus. Deste, pela adoração, aproxima o homem sua alma.', 'rascunho'),
  (650, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Origina-se de um sentimento inato a adoração, ou é fruto de ensino?', 'Sentimento inato, como o da existência de Deus. A consciência da sua fraqueza leva o homem a curvar-se diante daquele que o pode proteger.', 'rascunho'),
  (651, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Terá havido povos destituídos de todo sentimento de adoração?', 'Não, que nunca houve povos de ateus. Todos compreendem que acima de tudo há um Ente Supremo.', 'rascunho'),
  (652, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Poder-se-á considerar a lei natural como fonte originária da adoração?', 'A adoração está na lei natural, pois resulta de um sentimento inato no homem. Por essa razão é que existe entre todos os povos, se bem que sob formas diferentes.', 'rascunho'),
  (653, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Precisa de manifestações exteriores a adoração?', 'A adoração verdadeira é do coração. Em todas as vossas ações, lembrai- vos sempre de que o Senhor tem sobre vós o seu olhar." a) — Será útil a adoração exterior? 218 – Allan Kar dec "Sim, se não consistir num vão simulacro. É sempre útil dar um bom exemplo. Mas, os que somente por afetação e amor-próprio o fazem, desmentindo com o proceder a aparente piedade, mau exemplo dão e não imaginam o mal que causam.', 'rascunho'),
  (654, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Tem Deus preferência pelos que o adoram desta ou daquela maneira?', 'Deus prefere os que o adoram do fundo do coração, com sinceridade, fazendo o bem e evitando o mal, aos que julgam honrá-lo com cerimônias que os não tornam melhores para com os seus semelhantes." "Todos os homens são irmãos e filhos de Deus. Ele atrai a si todos os que lhe obedecem às leis, qualquer que seja a forma sob que as exprimam." "É hipócrita aquele cuja piedade se cifra nos atos exteriores. Mau exemplo dá todo aquele cuja adoração é afetada e contradiz o seu procedimento." "Declaro-vos que somente nos lábios e não na alma tem religião aquele que professa adorar o Cristo, mas que é orgulhoso, invejoso e cioso, duro e implacável para com outrem, ou ambicioso dos bens deste mundo. Deus, que tudo vê, dirá: o que conhece a verdade é cem vezes mais culpado do mal que faz, do que o selvagem ignorante que vive no deserto. E como tal será tratado no dia da justiça. Se um cego, ao passar, vos derriba, perdoá-lo-eis; se for um homem que enxerga perfeitamente bem, queixar-vos-eis e com razão." "Não pergunteis, pois, se alguma forma de adoração há que mais convenha, porque equivaleria a perguntardes se mais agrada a Deus ser adorado num idioma do que noutro. Ainda uma vez vos digo: até ele não chegam os cânticos, senão quando passam pela porta do coração.', 'rascunho'),
  (655, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Merece censura aquele que pratica uma religião em que não crê do fundo d’alma, fazendo-o apenas pelo respeito humano e para não escandalizar os que pensam de modo diverso?', 'Nisto, como em muitas outras coisas, a intenção constitui a regra. Não procede mal aquele que, assim fazendo, só tenha em vista respeitar as crenças de outrem. Procede melhor do que um que as ridiculize, porque, então, falta à caridade. Aquele, porém, que a pratique por interesse e por ambição se torna desprezível aos olhos de Deus e dos homens. A Deus não podem agradar os que fingem humilhar-se diante dele tão-somente para granjear o aplauso dos homens.', 'rascunho'),
  (656, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'À adoração individual será preferível a adoração em comum?', 'Reunidos pela comunhão dos pensamentos e dos sentimentos, mais força têm os homens para atrair a si os bons Espíritos. O mesmo se dá quando se reúnem para adorar a Deus. Não creiais, todavia, que menos valiosa seja a adoração particular, pois que cada um pode adorar a Deus pensando nele.', 'rascunho'),
  (657, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Têm, perante Deus, algum mérito os que se consagram à vida contemplativa, uma vez que nenhum mal fazem e só em Deus pensam?', 'Não, porquanto, se é certo que não fazem o mal, também o é que não fazem o bem e são inúteis. Demais, não fazer o bem já é um mal. Deus quer que o homem pense nele, mas não quer que só nele pense, pois que lhe impôs deveres a cumprir na Terra. Quem passa todo o tempo na meditação e na contemplação nada faz de meritório aos olhos de Deus, porque vive uma vida toda pessoal e inútil à Humanidade e Deus lhe pedirá contas do bem que não houver feito.', 'rascunho'),
  (658, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Agrada a Deus a prece?', 'A prece é sempre agradável a Deus, quando ditada pelo coração, pois, para ele, a intenção é tudo. Assim, preferível lhe é a prece do íntimo à prece lida, por muito bela que seja, se for lida mais com os lábios do que com o coração. Agrada- lhe a prece, quando dita com fé, com fervor e sinceridade. Mas, não creiais que o toque a do homem fútil, orgulhoso e egoísta, a menos que signifique, de sua parte, um ato de sincero arrependimento e de verdadeira humildade.', 'rascunho'),
  (659, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Qual o caráter geral da prece?', 'A prece é um ato de adoração. Orar a Deus é pensar nele; é aproximar-se dele; é pôr-se em comunicação com ele. A três coisas podemos propor-nos por meio da prece: louvar, pedir, agradecer.', 'rascunho'),
  (660, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'A prece torna melhor o homem?', 'Sim, porquanto aquele que ora com fervor e confiança se faz mais forte contra as tentações do mal e Deus lhe envia bons Espíritos para assisti-lo. É este um socorro que jamais se lhe recusa, quando pedido com sinceridade." a) — Como é que certas pessoas, que oram muito, são, não obstante, de mau-caráter, ciosas, invejosas, impertinentes, carentes de benevolência e de indulgência e até, algumas vezes, viciosas? "O essencial não é orar muito, mas orar bem. Essas pessoas supõem que todo o mérito está na longura da prece e fecham os olhos para os seus próprios defeitos. Fazem da prece uma ocupação, um emprego do tempo, nunca, porém, um estudo de si mesmas. A ineficácia, em tais casos, não é do remédio, sim da maneira por que o aplicam.', 'rascunho'),
  (661, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Poderemos utilmente pedir a Deus que perdoe as nossas faltas?', 'Deus sabe discernir o bem do mal; a prece não esconde as faltas. Aquele que a Deus pede perdão de suas faltas só o obtém mudando de proceder. As boas ações são a melhor prece, por isso que os atos valem mais que as palavras.', 'rascunho'),
  (662, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Pode-se, com utilidade, orar por outrem?', 'O Espírito de quem ora atua pela sua vontade de praticar o bem. Atrai a si, mediante a prece, os bons Espíritos e estes se associam ao bem que deseje fazer." 220 – Allan Kar dec O pensamento e a vontade representam em nós um poder de ação que alcança muito além dos limites da nossa esfera corporal. A prece que façamos por outrem é um ato dessa vontade. Se for ardente e sincera, pode chamar, em auxílio daquele por quem oramos, os bons Espíritos, que lhe virão sugerir bons pensamentos e dar a força de que necessitem seu corpo e sua alma. Mas, ainda aqui, a prece do coração é tudo, a dos lábios nada vale.', 'rascunho'),
  (663, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Podem as preces, que por nós mesmos fizermos, mudar a natureza das nossas provas e desviar-lhes o curso?', 'As vossas provas estão nas mãos de Deus e algumas há que têm de ser suportadas até ao fim; mas, Deus sempre leva em conta a resignação. A prece traz para junto de vós os bons Espíritos e, dando-vos estes a força de suportá-las corajosamente, menos rudes elas vos parecem. Hemos dito que a prece nunca é inútil, quando bem feita, porque fortalece aquele que ora, o que já constitui grande resultado. Ajuda-te a ti mesmo e o céu te ajudará, bem o sabes. Demais, não é possível que Deus mude a ordem da natureza ao sabor de cada um, porquanto o que, do vosso ponto de vista mesquinho e do da vossa vida efêmera, vos parece um grande mal é quase sempre um grande bem na ordem geral do Universo. Além disso, de quantos males não se constitui o homem o próprio autor, pela sua imprevidência ou pelas suas faltas? Ele é punido naquilo em que pecou. Todavia, as súplicas justas são atendidas mais vezes do que supondes. Julgais, de ordinário, que Deus não vos ouviu, porque não fez a vosso favor um milagre, enquanto que vos assiste por meios tão naturais que vos parecem obra do acaso ou da força das coisas. Muitas vezes também, as mais das vezes mesmo, ele vos sugere a idéia que vos fará sair da dificuldade pelo vosso próprio esforço.', 'rascunho'),
  (664, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Será útil que oremos pelos mortos e pelos Espíritos sofredores? E, neste caso, como lhes podem as nossas preces proporcionar alívio e abreviar os sofrimentos? Têm elas o poder de abrandar a justiça de Deus?', 'A prece não pode ter por efeito mudar os desígnios de Deus, mas a alma por quem se ora experimenta alívio, porque recebe assim um testemunho do interesse que inspira àquele que por ela pede e também porque o desgraçado sente sempre um refrigério, quando encontra almas caridosas que se compadecem de suas dores. Por outro lado, mediante a prece, aquele que ora concita o desgraçado ao arrependimento e ao desejo de fazer o que é necessário para ser feliz. Neste sentido é que se lhe pode abreviar a pena, se, por sua parte, ele secunda a prece com a boa vontade. O desejo de melhorar-se, despertado pela prece, atrai para junto do Espírito sofredor Espíritos melhores, que o vão esclarecer, consolar e dar-lhe esperanças. Jesus orava pelas ovelhas desgarradas, mostrando-vos, desse modo, que culpados vos tornaríeis, se não fizésseis o mesmo pelos que mais necessitam das vossas preces.', 'rascunho'),
  (665, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Que se deve pensar da opinião dos que rejeitam a prece em favor dos mortos, por não se achar prescrita no Evangelho?', 'Aos homens disse o Cristo: Amai-vos uns aos outros. Esta recomendação contém a de empregar o homem todos os meios possíveis para testemunhar aos outros homens afeição, sem haver entrado em minúcias quanto à maneira de atingir ele esse fim. Se é certo que nada pode fazer que o Criador, imagem da justiça perfeita, deixe de aplicá-la a todas as ações do Espírito, não menos certo é que a prece que lhe dirigis por aquele que vos inspira afeição constitui, para este, um testemunho de que dele vos lembrais, testemunho que forçosamente contribuirá para lhe suavizar os sofrimentos e consolá-lo. Desde que ele manifeste o mais ligeiro arrependimento, mas só então, é socorrido. Nunca, porém, será deixado na ignorância de que uma alma simpática com ele se ocupou. Ao contrário, será deixado na doce crença de que a intercessão dessa alma lhe foi útil. Daí resulta necessariamente, de sua parte, um sentimento de gratidão e afeto pelo que lhe deu essa prova de amizade ou de piedade. Em conseqüência, crescerá num e noutro, reciprocamente, o amor que o Cristo recomendava aos homens. Ambos, pois, se fizeram assim obedientes à lei de amor e de união de todos os seres, lei divina, de que resultará a unidade, objetivo e finalidade do Espírito." 7', 'rascunho'),
  (666, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Pode-se orar aos Espíritos?', 'Pode-se orar aos bons Espíritos, como sendo os mensageiros de Deus e os executores de suas vontades. O poder deles, porém, está em relação com a superioridade que tenham alcançado e dimana sempre do Senhor de todas as coisas, sem cuja permissão nada se faz. Eis por que as preces que se lhes dirigem só são eficazes, se bem aceitas por Deus.', 'rascunho'),
  (667, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Por que razão, não obstante ser falsa, a crença politeísta é uma das mais antigas e espalhadas?', 'A concepção de um Deus único não poderia existir no homem, senão como resultado do desenvolvimento de suas idéias. Incapaz, pela sua ignorância, de conceber um ser imaterial, sem forma determinada, atuando sobre a matéria, conferiu-lhe o homem atributos da natureza corpórea, isto é, uma forma e um aspecto e, desde então, tudo o que parecia ultrapassar os limites da inteligência comum era, para ele, uma divindade. Tudo o que não compreendia devia ser obra de uma potência sobrenatural. Daí a crer em tantas potências distintas quantos os efeitos que observava, não havia mais que um passo. Em todos os tempos, porém, houve homens instruídos, que compreenderam ser impossível a existência desses poderes múltiplos a governarem o mundo, sem uma direção superior, e que, em conseqüência, se elevaram à concepção de um Deus único.', 'rascunho'),
  (668, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Tendo-se produzido em todos os tempos e sendo conhecidos desde as primeiras idades do mundo, não haverão os fenômenos espíritas contribuído para a difusão da crença na pluralidade dos deuses?', 'Sem dúvida, porquanto, chamando deus a tudo o que era sobre-humano, os homens tinham por deuses os Espíritos. Daí veio que, quando um homem, pelas suas ações, pelo seu gênio, ou por um poder oculto que o vulgo não lograva 7 Resposta dada pelo Sr. Monod (Espírito), pastor protestante em Paris, morto em abril de 1856. A resposta anterior, nº 664, é do Espírito São Luís. 222 – Allan Kar dec compreender, se distinguia dos demais, faziam dele um deus e, por sua morte, lhe rendiam culto." A palavra deus tinha, entre os antigos, acepção muito ampla. Não indicava, como presentemente, uma personificação do Senhor da Natureza. Era uma qualificação genérica, que se dava a todo ser existente fora das condições da Humanidade. Ora, tendo-lhes as manifestações espíritas revelado a existência de seres incorpóreos a atuarem como potência da Natureza, a esses seres deram eles o nome de deuses, como lhes damos atualmente o de Espíritos. Pura questão de palavras, com a única diferença de que, na ignorância em que se achavam, mantida intencionalmente pelos que nisso tinham interesse, eles erigiram templos e altares muito lucrativos a tais deuses, ao passo que hoje os consideramos simples criaturas como nós, mais ou menos perfeitas e despidas de seus invólucros terrestres. Se estudarmos atentamente os diversos atributos das divindades pagãs, reconheceremos, sem esforço, todos os de que vemos dotados os Espíritos nos diferentes graus da escala espírita, o estado físico em que se encontram nos mundos superiores, todas as propriedades do perispírito e os papéis que desempenham nas coisas da Terra. Vindo iluminar o mundo com a sua divina luz, o Cristianismo não se propôs destruir uma coisa que está na Natureza. Orientou, porém, a adoração para Aquele a quem é devida. Quanto aos Espíritos, a lembrança deles se há perpetuado, conforme os povos, sob diversos nomes, e suas manifestações, que nunca deixaram de produzir-se, foram interpretadas de maneiras diferentes e muitas vezes exploradas sob o prestígio do mistério. Enquanto para a religião essas manifestações eram fenômenos miraculosos, para os incrédulos sempre foram embustes. Hoje, mercê de um estudo mais sério, feito à luz meridiana, o Espiritismo, escoimado das idéias supersticiosas que o ensombraram durante séculos, nos revela um dos maiores e mais sublimes princípios da Natureza.', 'rascunho'),
  (669, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Remonta à mais alta antiguidade o uso dos sacrifícios humanos. Como se explica que o homem tenha sido levado a crer que tais coisas pudessem agradar a Deus?', 'Primeiramente, porque não compreendia Deus como sendo a fonte da bondade. Nos povos primitivos a matéria sobrepuja o espírito; eles se entregam aos instintos do animal selvagem. Por isso é que, em geral, são cruéis; é que neles o senso moral ainda não se acha desenvolvido. Em segundo lugar, é natural que os homens primitivos acreditassem ter uma criatura animada muito mais valor, aos olhos de Deus, do que um corpo material. Foi isto que os levou a imolarem, primeiro, animais e, mais tarde, homens. De conformidade com a falsa crença que possuíam, pensavam que o valor do sacrifício era proporcional à importância da vítima. Na vida material, como geralmente a praticais, se houverdes de oferecer a alguém um presente, escolhê-lo-eis sempre de tanto maior valor quanto mais afeto e consideração quiserdes testemunhar a esse alguém. Assim tinha que ser, com relação a Deus, entre homens ignorantes." a) — De modo que os sacrifícios de animais precederam os sacrifícios humanos? "Sobre isso não pode haver a menor dúvida." b) — Então, de acordo com a explicação que vindes de dar, não foi de um sentimento de crueldade que se originaram os sacrifícios humanos? "Não; originaram-se de uma idéia errônea quanto à maneira de agradar a Deus. Considerai o que se deu com Abraão. Com o correr dos tempos, os homens entraram a abusar dessas práticas, imolando seus inimigos comuns, até mesmo seus inimigos particulares. Deus, entretanto, nunca exigiu sacrifícios, nem de homens, nem, sequer, de animais. Não há como imaginar-se que se lhe possa prestar culto, mediante a destruição inútil de suas criaturas.', 'rascunho'),
  (670, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Dar-se-á que alguma vez possam ter sido agradáveis a Deus os sacrifícios humanos praticados com piedosa intenção?', 'Não, nunca. Deus, porém, julga pela intenção. Sendo ignorantes os homens, natural era que supusessem praticar ato louvável imolando seus semelhantes. Nesses casos, Deus atentava unicamente na idéia que presidia ao ato e não neste. À proporção que se foram melhorando, os homens tiveram que reconhecer o erro em que laboravam e que reprovar tais sacrifícios, com que não podiam conformar-se as idéias de Espíritos esclarecidos. Digo — esclarecidos, porque os Espíritos tinham então a envolvê-los o véu material; mas, por meio do livre-arbítrio, possível lhes era vislumbrar suas origens e fim, e muitos, por intuição, já compreendiam o mal que praticavam, se bem que nem por isso deixassem de praticá-lo, para satisfazer às suas paixões.', 'rascunho'),
  (671, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Que devemos pensar das chamadas guerras santas? O sentimento que impele os povos fanáticos, tendo em vista agradar a Deus, a exterminarem o mais possível os que não partilham de suas crenças, poderá equiparar-se, quanto à origem, ao sentimento que os excitava outrora a sacrificarem seus semelhantes?', 'São impelidos pelos maus Espíritos e, fazendo a guerra aos seus semelhantes, contravêm à vontade de Deus, que manda ame cada um o seu irmão, como a si mesmo. Todas as religiões, ou, antes, todos os povos adoram um mesmo Deus, qualquer que seja o nome que lhe dêem. Por que então há de um fazer guerra a outro, sob o fundamento de ser a religião deste diferente da sua, ou por não ter ainda atingido o grau de progresso da dos povos cultos? Se são desculpáveis os povos de não crerem na palavra daquele que o Espírito de Deus animava e que Deus enviou, sobretudo os que não o viram e não lhe testemunharam os atos, como pretenderdes que creiam nessa palavra de paz, quando lhes ides levá-la de espada em punho? Eles têm que ser esclarecidos e devemos esforçar-nos por fazê-los conhecer a doutrina do Salvador, mediante a persuasão e com brandura, nunca a ferro e fogo. Em vossa maioria, não acreditais nas comunicações que temos com certos mortais; como quereríeis que estranhos acreditassem na vossa palavra, quando desmentis com os atos a doutrina que pregais?', 'rascunho'),
  (672, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'A oferenda feita a Deus, de frutos da terra, tinha a seus olhos mais mérito do que o sacrifício dos animais?', 'Já vos respondi, declarando que Deus julga segundo a intenção e que para ele pouca importância tinha o fato. Mais agradável evidentemente era a Deus que lhe oferecessem frutos da terra, em vez do sangue das vítimas. Como temos dito e 224 – Allan Kar dec sempre repetiremos, a prece proferida do fundo da alma é cem vezes mais agradável a Deus do que todas as oferendas que lhe possais fazer. Repito que a intenção é tudo, que o fato nada vale.', 'rascunho'),
  (673, 'Parte Terceira — Das leis morais', 'Capítulo II — Da lei de adoração', 'Não seria um meio de tornar essas oferendas agradáveis a Deus consagrá-las a minorar os sofrimentos daqueles a quem falta o necessário e, neste caso, o sacrifício dos animais, praticado com fim útil, não se tornaria meritório, ao passo que era abusivo quando para nada servia, ou só aproveitava aos que de nada precisavam? Não haveria qualquer coisa de verdadeiramente piedoso em consagrar-se aos pobres as primícias dos bens que Deus nos concede na Terra?', 'Deus abençoa sempre os que fazem o bem. O melhor meio de honrá-lo consiste em minorar os sofrimentos dos pobres e dos aflitos. Não quero dizer com isto que ele desaprove as cerimônias que praticais para lhe dirigirdes as vossas preces. Muito dinheiro, porém, aí se gasta que poderia ser empregado mais utilmente do que o é. Deus ama a simplicidade em tudo. O homem que se atém às exterioridades e não ao coração é um Espírito de vistas acanhadas. Dizei, em consciência, se Deus deve atender mais à forma do que ao fundo.', 'rascunho'),
  (674, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'A necessidade do trabalho é lei da Natureza?', 'O trabalho é lei da Natureza, por isso mesmo que constitui uma necessidade, e a civilização obriga o homem a trabalhar mais, porque lhe aumenta as necessidades e os gozos.', 'rascunho'),
  (675, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'Por trabalho só se devem entender as ocupações materiais?', 'Não; o Espírito trabalha, assim como o corpo. Toda ocupação útil é trabalho.', 'rascunho'),
  (676, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'Por que o trabalho se impõe ao homem?', 'Por ser uma conseqüência da sua natureza corpórea. É expiação e, ao mesmo tempo, meio de aperfeiçoamento da sua inteligência. Sem o trabalho, o homem permaneceria sempre na infância, quanto à inteligência. Por isso é que seu alimento, sua segurança e seu bem-estar dependem do seu trabalho e da sua atividade. Ao extremamente fraco de corpo outorgou Deus a inteligência, em compensação. Mas é sempre um trabalho.', 'rascunho'),
  (677, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'Por que provê a Natureza, por si mesma, a todas as necessidades dos animais?', 'Tudo em a Natureza trabalha. Como tu, trabalham os animais, mas o trabalho deles, de acordo com a inteligência de que dispõem, se limita a cuidarem da própria conservação. Daí vem que do trabalho não lhes resulta progresso, ao passo que o do homem visa duplo fim: a conservação do corpo e o desenvolvimento da faculdade de pensar, o que também é uma necessidade e o eleva acima de si mesmo. Quando digo que o trabalho dos animais se cifra no cuidarem da própria conservação, refiro-me ao objetivo com que trabalham. Entretanto, provendo às suas necessidades materiais, eles se constituem, inconscientemente, executores dos desígnios do Criador e, assim, o trabalho que executam também concorre para a 226 – Allan Kar dec realização do objetivo final da Natureza, se bem quase nunca lhe descubrais o resultado imediato.', 'rascunho'),
  (678, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'Em os mundos mais aperfeiçoados, os homens se acham submetidos à mesma necessidade de trabalhar?', 'A natureza do trabalho está em relação com a natureza das necessidades. Quanto menos materiais são estas, menos material é o trabalho. Mas, não deduzais daí que o homem se conserve inativo e inútil. A ociosidade seria um suplício, em vez de ser um benefício.', 'rascunho'),
  (679, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'Achar-se-á isento da lei do trabalho o homem que possua bens suficientes para lhe assegurarem a existência?', 'Do trabalho material, talvez; não, porém, da obrigação de tornar-se útil, conforme aos meios de que disponha, nem de aperfeiçoar a sua inteligência ou a dos outros, o que também é trabalho. Aquele a quem Deus facultou a posse de bens suficientes a lhe garantirem a existência não está, é certo, constrangido a alimentar- se com o suor do seu rosto, mas tanto maior lhe é a obrigação de ser útil aos seus semelhantes, quanto mais ocasiões de praticar o bem lhe proporciona o adiantamento que lhe foi feito.', 'rascunho'),
  (680, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'Não há homens que se encontram impossibilitados de trabalhar no que quer que seja e cuja existência é, portanto, inútil?', 'Deus é justo e, pois, só condena aquele que voluntariamente tornou inútil a sua existência, porquanto esse vive a expensas do trabalho dos outros. Ele quer que cada um seja útil, de acordo com as suas faculdades.', 'rascunho'),
  (681, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'A lei da Natureza impõe aos filhos a obrigação de trabalharem para seus pais?', 'Certamente, do mesmo modo que os pais têm que trabalhar para seus filhos. Foi por isso que Deus fez do amor filial e do amor paterno um sentimento natural. Foi para que, por essa afeição recíproca, os membros de uma família se sentissem impelidos a ajudarem-se mutuamente, o que, aliás, com muita freqüência se esquece na vossa sociedade atual.', 'rascunho'),
  (682, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'Sendo uma necessidade para todo aquele que trabalha, o repouso não é também uma lei da Natureza?', 'Sem dúvida. O repouso serve para a reparação das forças do corpo e também é necessário para dar um pouco mais de liberdade à inteligência, a fim de que se eleve acima da matéria.', 'rascunho'),
  (683, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'Qual o limite do trabalho?', 'O das forças. Em suma, a esse respeito Deus deixa inteiramente livre o homem.', 'rascunho'),
  (684, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'Que se deve pensar dos que abusam de sua autoridade, impondo a seus inferiores excessivo trabalho?', 'Isso é uma das piores ações. Todo aquele que tem o poder de mandar é responsável pelo excesso de trabalho que imponha a seus inferiores, porquanto, assim fazendo, transgride a lei de Deus.', 'rascunho'),
  (685, 'Parte Terceira — Das leis morais', 'Capítulo III — Da lei do trabalho', 'Tem o homem o direito de repousar na velhice?', 'Sim, que a nada é obrigado, senão de acordo com as suas forças." a) — Mas, que há de fazer o velho que precisa trabalhar para viver e não pode? "O forte deve trabalhar para o fraco. Não tendo este família, a sociedade deve fazer as vezes desta. É a lei de caridade." Não basta se diga ao homem que lhe corre o dever de trabalhar. É preciso que aquele que tem de prover à sua existência por meio do trabalho encontre em que se ocupar, o que nem sempre acontece. Quando se generaliza, a suspensão do trabalho assume as proporções de um flagelo, qual a miséria. A ciência econômica procura remédio para isso no equilíbrio entre a produção e o consumo. Mas, esse equilíbrio, dado seja possível estabelecer-se, sofrerá sempre intermitências, durante as quais não deixa o trabalhador de ter que viver. Há um elemento, que se não costuma fazer pesar na balança e sem o qual a ciência econômica não passa de simples teoria. Esse elemento é a educação, não a educação intelectual, mas a educação moral. Não nos referimos, porém, à educação moral pelos livros e sim à que consiste na arte de formar os caracteres, à que incute hábitos, porquanto a educação é o conjunto dos hábitos adquiridos. Considerando-se a aluvião de indivíduos que todos os dias são lançados na torrente da população, sem princípios, sem freio e entregues a seus próprios instintos, serão de espantar as conseqüências desastrosas que daí decorrem? Quando essa arte for conhecida, compreendida e praticada, o homem terá no mundo hábitos de ordem e de previdência para consigo mesmo e para com os seus, de respeito a tudo o que é respeitável, hábitos que lhe permitirão atravessar menos penosamente os maus dias inevitáveis. A desordem e a imprevidência são duas chagas que só uma educação bem entendida pode curar. Esse o ponto de partida, o elemento real do bem-estar, o penhor da segurança de todos. 228 – Allan Kar dec', 'rascunho'),
  (686, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'É lei da Natureza a reprodução dos seres vivos?', 'Evidentemente. Sem a reprodução, o mundo corporal pereceria.', 'rascunho'),
  (687, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Indo sempre a população na progressão crescente que vemos, chegará tempo em que seja excessiva na Terra?', 'Não, Deus a isso provê e mantém sempre o equilíbrio. Ele coisa alguma inútil faz. O homem, que apenas vê um canto do quadro da Natureza, não pode julgar da harmonia do conjunto.', 'rascunho'),
  (688, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Há, neste momento, raças humanas que evidentemente decrescem. Virá momento em que terão desaparecido da Terra?', 'Assim acontecerá, de fato. É que outras lhes terão tomado o lugar, como outras um dia tomarão o da vossa.', 'rascunho'),
  (689, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Os homens atuais formam uma criação nova, ou são descendentes aperfeiçoados dos seres primitivos?', 'São os mesmos Espíritos que voltaram, para se aperfeiçoar em novos corpos, mas que ainda estão longe da perfeição. Assim, a atual raça humana, que, pelo seu crescimento, tende a invadir toda a Terra e a substituir as raças que se extinguem, terá sua fase de decrescimento e de desaparição. Substituí-la-ão outras raças mais aperfeiçoadas, que descenderão da atual, como os homens civilizados de hoje descendem dos seres brutos e selvagens dos tempos primitivos.', 'rascunho'),
  (690, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Do ponto de vista físico, são de criação especial os corpos da raça atual, ou procedem dos corpos primitivos, mediante reprodução?', 'A origem das raças se perde na noite dos tempos. Mas, como pertencem todas à grande família humana, qualquer que tenha sido o tronco de cada uma, elas puderam aliar-se entre si e produzir tipos novos.', 'rascunho'),
  (691, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Qual, do ponto de vista físico, o caráter distintivo e dominante das raças primitivas?', 'Desenvolvimento da força bruta, à custa da força intelectual. Agora, dá-se o contrário: o homem faz mais pela inteligência do que pela força do corpo. Todavia, faz cem vezes mais, porque soube tirar proveito das forças da Natureza, o que não conseguem os animais.', 'rascunho'),
  (692, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Será contrário à lei da Natureza o aperfeiçoamento das raças animais e vegetais pela Ciência? Seria mais conforme a essa lei deixar que as coisas seguissem seu curso normal?', 'Tudo se deve fazer para chegar à perfeição e o próprio homem é um instrumento de que Deus se serve para atingir seus fins. Sendo a perfeição a meta para que tende a Natureza, favorecer essa perfeição é corresponder às vistas de Deus." a) — Mas, geralmente, os esforços que o homem emprega para conseguir a melhoria das raças nascem de um sentimento pessoal e não objetivam senão o acréscimo de seus gozos. Isto não lhe diminui o mérito? "Que importa seja nulo o seu merecimento, desde que o progresso se realize? Cabe-lhe tornar meritório, pela intenção, o seu trabalho. Demais, mediante esse trabalho, ele exercita e desenvolve a inteligência e sob este aspecto é que maior proveito tira.', 'rascunho'),
  (693, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'São contrários à lei da Natureza as leis e os costumes humanos que têm por fim ou por efeito criar obstáculos à reprodução?', 'Tudo o que embaraça a Natureza em sua marcha é contrário à lei geral." a) — Entretanto, há espécies de seres vivos, animais e plantas, cuja reprodução indefinida seria nociva a outras espécies e das quais o próprio homem acabaria por ser vítima. Pratica ele ato repreensível, impedindo essa reprodução? "Deus concedeu ao homem, sobre todos os seres vivos, um poder de que ele deve usar, sem abusar. Pode, pois, regular a reprodução, de acordo com as necessidades. Não deve opor-se-lhe sem necessidade. A ação inteligente do homem é um contrapeso que Deus dispôs para restabelecer o equilíbrio entre as forças da Natureza e é ainda isso o que o distingue dos animais, porque ele obra com conhecimento de causa. Mas, os mesmos animais também concorrem para a existência desse equilíbrio, porquanto o instinto de destruição que lhes foi dado faz 230 – Allan Kar dec com que, provendo à própria conservação, obstem ao desenvolvimento excessivo, quiçá perigoso, das espécies animais e vegetais de que se alimentam.', 'rascunho'),
  (694, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Que se deve pensar dos usos, cujo efeito consiste em obstar à reprodução, para satisfação da sensualidade?', 'Isso prova a predominância do corpo sobre a alma e quanto o homem é material.', 'rascunho'),
  (695, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Será contrário à lei da Natureza o casamento, isto é, a união permanente de dois seres?', 'É um progresso na marcha da Humanidade.', 'rascunho'),
  (696, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Que efeito teria sobre a sociedade humana a abolição do casamento?', 'Seria uma regressão à vida dos animais." O estado de natureza é o da união livre e fortuita dos sexos. O casamento constitui um dos primeiros atos de progresso nas sociedades humanas, porque estabelece a solidariedade fraterna e se observa entre todos os povos, se bem que em condições diversas. A abolição do casamento seria, pois, regredir à infância da Humanidade e colocaria o homem abaixo mesmo de certos animais que lhe dão o exemplo de uniões constantes.', 'rascunho'),
  (697, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Está na lei da Natureza, ou somente na lei humana, a indissolubilidade absoluta do casamento?', 'É uma lei humana muito contrária à da Natureza. Mas os homens podem modificar suas leis; só as da Natureza são imutáveis.', 'rascunho'),
  (698, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'O celibato voluntário representa um estado de perfeição meritório aos olhos de Deus?', 'Não, e os que assim vivem, por egoísmo, desagradam a Deus e enganam o mundo.', 'rascunho'),
  (699, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Da parte de certas pessoas, o celibato não será um sacrifício que fazem com o fim de se votarem, de modo mais completo, ao serviço da Humanidade?', 'Isso é muito diferente. Eu disse: por egoísmo. Todo sacrifício pessoal é meritório, quando feito para o bem. Quanto maior o sacrifício, tanto maior o mérito." Não é possível que Deus se contradiga, nem que ache mau o que ele próprio fez. Nenhum mérito, portanto, pode haver na violação da sua lei. Mas, se o celibato, em si mesmo, não é um estado meritório, outro tanto não se dá quando constitui, pela renúncia às alegrias da família, um sacrifício praticado em prol da Humanidade. Todo sacrifício pessoal, tendo em vista o bem e sem qualquer idéia egoísta, eleva o homem acima da sua condição material.', 'rascunho'),
  (700, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'A igualdade numérica, que mais ou menos existe entre os sexos, constitui indício da proporção em que devam unir-se?', 'Sim, porquanto tudo, em a Natureza, tem um fim.', 'rascunho'),
  (701, 'Parte Terceira — Das leis morais', 'Capítulo IV — Da lei de reprodução', 'Qual das duas, a poligamia ou a monogamia, é mais conforme à lei da Natureza?', 'A poligamia é lei humana cuja abolição marca um progresso social. O casamento, segundo as vistas de Deus, tem que se fundar na afeição dos seres que se unem. Na poligamia não há afeição real: há apenas sensualidade." Se a poligamia fosse conforme à lei da Natureza, devera ter possibilidade de tornar-se universal, o que seria materialmente impossível, dada a igualdade numérica dos sexos. Deve ser considerada como um uso ou legislação especial apropriada a certos costumes e que o aperfeiçoamento social fez que desaparecesse pouco a pouco. 232 – Allan Kar dec', 'rascunho'),
  (702, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'É lei da Natureza o instinto de conservação?', 'Sem dúvida. Todos os seres vivos o possuem, qualquer que seja o grau de sua inteligência. Nuns, é puramente maquinal, raciocinado em outros.', 'rascunho'),
  (703, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Com que fim outorgou Deus a todos os seres vivos o instinto de conservação?', 'Porque todos têm que concorrer para cumprimento dos desígnios da Providência. Por isso foi que Deus lhes deu a necessidade de viver. Acresce que a vida é necessária ao aperfeiçoamento dos seres. Eles o sentem instintivamente, sem disso se aperceberem.', 'rascunho'),
  (704, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Tendo dado ao homem a necessidade de viver, Deus lhe facultou, em todos os tempos, os meios de o conseguir?', 'Certo, e se ele os não encontra, é que não os compreende. Não fora possível que Deus criasse para o homem a necessidade de viver, sem lhe dar os meios de consegui-lo. Essa a razão por que faz que a Terra produza de modo a proporcionar o necessário aos que a habitam, visto que só o necessário é útil. O supérfluo nunca o é.', 'rascunho'),
  (705, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Por que nem sempre a terra produz bastante para fornecer ao homem o necessário?', 'É que, ingrato, o homem a despreza! Ela, no entanto, é excelente mãe. Muitas vezes, também, ele acusa a Natureza do que só é resultado da sua imperícia ou da sua imprevidência. A terra produziria sempre o necessário, se com o necessário soubesse o homem contentar-se. Se o que ela produz não lhe basta a todas as necessidades, é que ele emprega no supérfluo o que poderia ser aplicado no necessário. Olha o árabe no deserto. Acha sempre de que viver, porque não cria para si necessidades factícias. Desde que haja desperdiçado a metade dos produtos em satisfazer a fantasias, que motivos tem o homem para se espantar de nada encontrar no dia seguinte e para se queixar de estar desprovido de tudo, quando chegam os dias de penúria? Em verdade vos digo, imprevidente não é a Natureza, é o homem, que não sabe regrar o seu viver.', 'rascunho'),
  (706, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Por bens da Terra unicamente se devem entender os produtos do solo?', 'O solo é a fonte primacial donde dimanam todos os outros recursos, pois que, em definitivo, estes recursos são simples transformações dos produtos do solo. Por bens da Terra se deve, pois, entender tudo de que o homem pode gozar neste mundo.', 'rascunho'),
  (707, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'É freqüente a certos indivíduos faltarem os meios de subsistência, ainda quando os cerca a abundância. A que se deve atribuir isso?', 'Ao egoísmo dos homens, que nem sempre fazem o que lhes cumpre. Depois e as mais das vezes, devem-no a si mesmos. Buscai e achareis; estas palavras não querem dizer que, para achar o que deseje, basta que o homem olhe para a terra, mas que lhe é preciso procurá-lo, não com indolência, e sim com ardor e perseverança, sem desanimar ante os obstáculos, que muito amiúde são simples meios de que se utiliza a Providência, para lhe experimentar a constância, a paciência e a firmeza." Se é certo que a Civilização multiplica as necessidades, também o é que multiplica as fontes de trabalho e os meios de viver. Forçoso, porém, é convir em que, a tal respeito, muito ainda lhe resta por fazer. Quando ela houver concluído a sua obra, ninguém deverá haver que possa queixar-se de lhe faltar o necessário, a não ser por sua própria culpa. A desgraça, para muitos, provém de enveredarem por uma senda diversa da que a Natureza lhes traça. É então que lhes falece a inteligência para o bom êxito. Para todos há lugar ao Sol, mas com a condição de que cada um ocupe o seu e não o dos outros. A Natureza não pode ser responsável pelos defeitos da organização social, nem pelas conseqüências da ambição e do amor-próprio. Fora preciso, entretanto, ser-se cego, para se não reconhecer o progresso que, por esse lado, têm feito os povos mais adiantados. Graças aos louváveis esforços que, juntas, a Filantropia e a Ciência não cessam de despender para melhorar a condição material dos homens e malgrado ao crescimento incessante das populações, a insuficiência da produção se acha atenuada, pelo menos em grande parte, e os anos mais calamitosos do presente não se podem de modo algum comparar aos de outrora. A higiene pública, elemento tão essencial da força e da saúde, a higiene pública, que nossos pais não conheceram, é objeto de esclarecida solicitude. O infortúnio e o sofrimento encontram onde se refugiem. Por toda parte a Ciência contribui para acrescer o bem-estar. Poder-se-á dizer que já se haja chegado à perfeição? Oh! não, certamente; mas, o que já se fez deixa prever o que, com perseverança, se logrará conseguir, se o homem se mostrar bastante avisado para procurar a sua felicidade nas coisas positivas e sérias e não em utopias que o levam a recuar em vez de fazê-lo avançar. 234 – Allan Kar dec', 'rascunho'),
  (708, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Não há situações em as quais os meios de subsistência de maneira alguma dependem da vontade do homem, sendo-lhe a privação do de que mais imperiosamente necessita uma conseqüência da força mesma das coisas?', 'É isso uma prova, muitas vezes cruel, que lhe compete sofrer e à qual sabia ele de antemão que viria a estar exposto. Seu mérito então consiste em submeter-se à vontade de Deus, desde que a sua inteligência nenhum meio lhe faculta de sair da dificuldade. Se a morte vier colhê-lo, cumpre-lhe recebê-la sem murmurar, ponderando que a hora da verdadeira libertação soou e que o desespero no derradeiro momento pode ocasionar-lhe a perda do fruto de toda a sua resignação.', 'rascunho'),
  (709, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Terão cometido crime os que, em certas situações críticas, se viram na contingência de sacrificar seus semelhantes, para matar a fome? Se houve crime, não teve este a atenuá-lo a necessidade de viver, que resulta do instinto de conservação?', 'Já respondi, quando disse que há mais merecimento em sofrer todas as provações da vida com coragem e abnegação. Em tal caso, há homicídio e crime de lesa-natureza, falta que é duplamente punida.', 'rascunho'),
  (710, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Nos mundos de mais apurada organização, têm os seres vivos necessidade de alimentar-se?', 'Têm, mas seus alimentos estão em relação com a sua natureza. Tais alimentos não seriam bastante substanciosos para os vossos estômagos grosseiros; assim como os deles não poderiam digerir os vossos alimentos.', 'rascunho'),
  (711, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'O uso dos bens da Terra é um direito de todos os homens?', 'Esse direito é conseqüente da necessidade de viver. Deus não imporia um dever sem dar ao homem o meio de cumpri-lo.', 'rascunho'),
  (712, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Com que fim pôs Deus atrativos no gozo dos bens materiais?', 'Para instigar o homem ao cumprimento da sua missão e para experimentá- lo por meio da tentação." a) — Qual o objetivo dessa tentação? "Desenvolver-lhe a razão, que deve preservá-lo dos excessos." Se o homem só fosse instigado a usar dos bens terrenos pela utilidade que têm, sua indiferença houvera talvez comprometido a harmonia do Universo. Deus imprimiu a esse uso o atrativo do prazer, porque assim é o homem impelido ao cumprimento dos desígnios providenciais. Mas, além disso, dando àquele uso esse atrativo, quis Deus também experimentar o homem por meio da tentação, que o arrasta para o abuso, de que deve a razão defendê-lo.', 'rascunho'),
  (713, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Traçou a Natureza limites aos gozos?', 'Traçou, para vos indicar o limite do necessário. Mas, pelos vossos excessos, chegais à saciedade e vos punis a vós mesmos.', 'rascunho'),
  (714, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Que se deve pensar do homem que procura nos excessos de todo gênero o requinte dos gozos?', 'Pobre criatura! mais digna é de lástima que de inveja, pois bem perto está da morte!" a) — Perto da morte física, ou da morte moral? "De ambas." O homem, que procura nos excessos de todo gênero o requinte do gozo, coloca-se abaixo do bruto, pois que este sabe deter-se, quando satisfeita a sua necessidade. Abdica da razão que Deus lhe deu por guia e quanto maiores forem seus excessos, tanto maior preponderância confere ele à sua natureza animal sobre a sua natureza espiritual. As doenças, as enfermidades e, ainda, a morte, que resultam do abuso, são, ao mesmo tempo, o castigo à transgressão da lei de Deus.', 'rascunho'),
  (715, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Como pode o homem conhecer o limite do necessário?', 'Aquele que é ponderado o conhece por intuição. Muitos só chegam a conhecê-lo por experiência e à sua própria custa.', 'rascunho'),
  (716, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Mediante a organização que nos deu, não traçou a Natureza o limite das nossas necessidades?', 'Sem dúvida, mas o homem é insaciável. Por meio da organização que lhe deu, a Natureza lhe traçou o limite das necessidades; porém, os vícios lhe alteraram a constituição e lhe criaram necessidades que não são reais.', 'rascunho'),
  (717, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Que se há de pensar dos que açambarcam os bens da Terra para se proporcionarem o supérfluo, com prejuízo daqueles a quem falta o necessário?', 'Olvidam a lei de Deus e terão que responder pelas privações que houverem causado aos outros." Nada tem de absoluto o limite entre o necessário e o supérfluo. A Civilização criou necessidades que o selvagem desconhece e os Espíritos que ditaram os preceitos acima não pretendem que o homem civilizado deva viver como o selvagem. Tudo é relativo, cabendo à razão regrar as coisas. A Civilização desenvolve o senso moral e, ao mesmo tempo, o sentimento de caridade, que leva os homens a se prestarem mútuo apoio. Os que vivem à custa das privações dos outros exploram, em seu proveito, os benefícios da Civilização. Desta têm apenas o verniz, como muitos há que da religião só têm a máscara.', 'rascunho'),
  (718, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'A lei de conservação obriga o homem a prover às necessidades do corpo?', 'Sim, porque, sem força e saúde, impossível é o trabalho." 236 – Allan Kar dec', 'rascunho'),
  (719, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Merece censura o homem, por procurar o bem-estar?', 'É natural o desejo do bem-estar. Deus só proíbe o abuso, por ser contrário à conservação. Ele não condena a procura do bem-estar, desde que não seja conseguido à custa de outrem e não venha a diminuir-vos nem as forças físicas, nem as forças morais.', 'rascunho'),
  (720, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'São meritórias aos olhos de Deus as privações voluntárias, com o objetivo de uma expiação igualmente voluntária?', 'Fazei o bem aos vossos semelhantes e mais mérito tereis." a) — Haverá privações voluntárias que sejam meritórias? "Há: a privação dos gozos inúteis, porque desprende da matéria o homem e lhe eleva a alma. Meritório é resistir à tentação que arrasta ao excesso ou ao gozo das coisas inúteis; é o homem tirar do que lhe é necessário para dar aos que carecem do bastante. Se a privação não passar de simulacro, será uma irrisão.', 'rascunho'),
  (721, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'É meritória, de qualquer ponto de vista, a vida de mortificações ascéticas que desde a mais remota antiguidade teve praticantes no seio de diversos povos?', 'Procurai saber a quem ela aproveita e tereis a resposta. Se somente serve para quem a pratica e o impede de fazer o bem, é egoísmo, seja qual for o pretexto com que entendam de colori-la. Privar-se a si mesmo e trabalhar para os outros, tal a verdadeira mortificação, segundo a caridade cristã.', 'rascunho'),
  (722, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Será racional a abstenção de certos alimentos, prescrita a diversos povos?', 'Permitido é ao homem alimentar-se de tudo o que lhe não prejudique a saúde. Alguns legisladores, porém, com um fim útil, entenderam de interdizer o uso de certos alimentos e, para maior autoridade imprimirem às suas leis, apresentaram- nas como emanadas de Deus.', 'rascunho'),
  (723, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'A alimentação animal é, com relação ao homem, contrária à lei da Natureza?', 'Dada a vossa constituição física, a carne alimenta a carne, do contrário o homem perece. A lei de conservação lhe prescreve, como um dever, que mantenha suas forças e sua saúde, para cumprir a lei do trabalho. Ele, pois, tem que se alimentar conforme o reclame a sua organização.', 'rascunho'),
  (724, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Será meritório abster-se o homem da alimentação animal, ou de outra qualquer, por expiação?', 'Sim, se praticar essa privação em benefício dos outros. Aos olhos de Deus, porém, só há mortificação, havendo privação séria e útil. Por isso é que qualificamos de hipócritas os que apenas aparentemente se privam de alguma coisa.', 'rascunho'),
  (725, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Que se deve pensar das mutilações operadas no corpo do homem ou dos animais?', 'A que propósito, semelhante questão? Ainda uma vez: inquiri sempre vós mesmos se é útil aquilo de que porventura se trate. A Deus não pode agradar o que seja inútil e o que for nocivo lhe será sempre desagradável. Porque, ficai sabendo, Deus só é sensível aos sentimentos que elevam para ele a alma. Obedecendo-lhe à lei e não a violando é que podereis forrar-vos ao jugo da vossa matéria terrestre.', 'rascunho'),
  (726, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Visto que os sofrimentos deste mundo nos elevam, se os suportarmos devidamente, dar-se-á que também nos elevam os que nós mesmos nos criamos?', 'Os sofrimentos naturais são os únicos que elevam, porque vêm de Deus. Os sofrimentos voluntários de nada servem, quando não concorrem para o bem de outrem. Supões que se adiantam no caminho do progresso os que abreviam a vida, mediante rigores sobre-humanos, como o fazem os bonzos, os faquires e alguns fanáticos de muitas seitas? Por que de preferência não trabalham pelo bem de seus semelhantes? Vistam o indigente; consolem o que chora; trabalhem pelo que está enfermo; sofram privações para alívio dos infelizes e então suas vidas serão úteis e, portanto, agradáveis a Deus. Sofrer alguém voluntariamente, apenas por seu próprio bem, é egoísmo; sofrer pelos outros é caridade: tais os preceitos do Cristo.', 'rascunho'),
  (727, 'Parte Terceira — Das leis morais', 'Capítulo V — Da lei de conservação', 'Uma vez que não devemos criar sofrimentos voluntários, que nenhuma utilidade tenham para outrem, deveremos cuidar de preservar-nos dos que prevejamos ou nos ameacem?', 'Contra os perigos e os sofrimentos é que o instinto de conservação foi dado a todos os seres. Fustigai o vosso espírito e não o vosso corpo, mortificai o vosso orgulho, sufocai o vosso egoísmo, que se assemelha a uma serpente a vos roer o coração, e fareis muito mais pelo vosso adiantamento do que infligindo-vos rigores que já não são deste século." 238 – Allan Kar dec', 'rascunho'),
  (728, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'É lei da Natureza a destruição?', 'Preciso é que tudo se destrua para renascer e se regenerar. Porque, o que chamais destruição não passa de uma transformação, que tem por fim a renovação e melhoria dos seres vivos." a) — O instinto de destruição teria sido dado aos seres vivos por desígnios providenciais? "As criaturas são instrumentos de que Deus se serve para chegar aos fins que objetiva. Para se alimentarem, os seres vivos reciprocamente se destroem, destruição esta que obedece a um duplo fim: manutenção do equilíbrio na reprodução, que poderia tornar-se excessiva, e utilização dos despojos do invólucro exterior que sofre a destruição. Esse invólucro é simples acessório e não a parte essencial do ser pensante. A parte essencial é o princípio inteligente, que não se pode destruir e se elabora nas metamorfoses diversas por que passa.', 'rascunho'),
  (729, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Se a regeneração dos seres faz necessária a destruição, por que os cerca a Natureza de meios de preservação e conservação?', 'A fim de que a destruição não se dê antes de tempo. Toda destruição antecipada obsta ao desenvolvimento do princípio inteligente. Por isso foi que Deus fez que cada ser experimentasse a necessidade de viver e de se reproduzir.', 'rascunho'),
  (730, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Uma vez que a morte nos faz passar a uma vida melhor, nos livra dos males desta, sendo, pois, mais de desejar do que de temer, por que lhe tem o homem, instintivamente, tal horror, que ela lhe é sempre motivo de apreensão?', 'Já dissemos que o homem deve procurar prolongar a vida, para cumprir a sua tarefa. Tal o motivo por que Deus lhe deu o instinto de conservação, instinto que o sustenta nas provas. A não ser assim, ele muito freqüentemente se entregaria ao desânimo. A voz íntima, que o induz a repelir a morte, lhe diz que ainda pode realizar alguma coisa pelo seu progresso. A ameaça de um perigo constitui aviso, para que se aproveite da dilação que Deus lhe concede. Mas, ingrato, o homem rende graças mais vezes à sua estrela do que ao seu Criador.', 'rascunho'),
  (731, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Por que, ao lado dos meios de conservação, colocou a Natureza os agentes de destruição?', 'É o remédio ao lado do mal. Já dissemos: para manter o equilíbrio e servir de contrapeso.', 'rascunho'),
  (732, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Será idêntica, em todos os mundos, a necessidade de destruição?', 'Guarda proporções com o estado mais ou menos material dos mundos. Cessa, quando o físico e o moral se acham mais depurados. Muito diversas são as condições de existência nos mundos mais adiantados do que o vosso.', 'rascunho'),
  (733, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Entre os homens da Terra existirá sempre a necessidade da destruição?', 'Essa necessidade se enfraquece no homem, à medida que o Espírito sobrepuja a matéria. Assim é que, como podeis observar, o horror à destruição cresce com o desenvolvimento intelectual e moral.', 'rascunho'),
  (734, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Em seu estado atual, tem o homem direito ilimitado de destruição sobre os animais?', 'Tal direito se acha regulado pela necessidade, que ele tem, de prover ao seu sustento e à sua segurança. O abuso jamais constituiu direito.', 'rascunho'),
  (735, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Que se deve pensar da destruição, quando ultrapassa os limites que as necessidades e a segurança traçam? Da caça, por exemplo, quando não objetiva senão o prazer de destruir sem utilidade?', 'Predominância da bestialidade sobre a natureza espiritual. Toda destruição que excede os limites da necessidade é uma violação da lei de Deus. Os animais só destroem para satisfação de suas necessidades; enquanto que o homem, dotado de livre-arbítrio, destrói sem necessidade. Terá que prestar contas do abuso da liberdade que lhe foi concedida, pois isso significa que cede aos maus instintos.', 'rascunho'),
  (736, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Especial merecimento terão os povos que levam ao excesso o escrúpulo, quanto à destruição dos animais?', 'Esse excesso, no tocante a um sentimento louvável em si mesmo, se torna abusivo e o seu merecimento fica neutralizado por abusos de muitas outras espécies. Entre tais povos, há mais temor supersticioso do que verdadeira bondade.', 'rascunho'),
  (737, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Com que fim fere Deus a Humanidade por meio de flagelos destruidores? 240 – Allan Kar dec', 'Para fazê-la progredir mais depressa. Já não dissemos ser a destruição uma necessidade para a regeneração moral dos Espíritos, que, em cada nova existência, sobem um degrau na escala do aperfeiçoamento? Preciso é que se veja o objetivo, para que os resultados possam ser apreciados. Somente do vosso ponto de vista pessoal os apreciais; daí vem que os qualificais de flagelos, por efeito do prejuízo que vos causam. Essas subversões, porém, são freqüentemente necessárias para que mais pronto se dê o advento de uma melhor ordem de coisas e para que se realize em alguns anos o que teria exigido muitos séculos.', 'rascunho'),
  (738, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Para conseguir a melhora da Humanidade, não podia Deus empregar outros meios que não os flagelos destruidores?', 'Pode e os emprega todos os dias, pois que deu a cada um os meios de progredir pelo conhecimento do bem e do mal. O homem, porém não se aproveita desses meios. Necessário, portanto, se torna que seja castigado no seu orgulho e que se lhe faça sentir a sua fraqueza." a) — Mas, nesses flagelos, tanto sucumbe o homem de bem como o perverso. Será justo isso? "Durante a vida, o homem tudo refere ao seu corpo; entretanto, de maneira diversa pensa depois da morte. Ora, conforme temos dito, a vida do corpo bem pouca coisa é. Um século no vosso mundo não passa de um relâmpago na eternidade. Logo, nada são os sofrimentos de alguns dias ou de alguns meses, de que tanto vos queixais. Representam um ensino que se vos dá e que vos servirá no futuro. Os Espíritos, que preexistem e sobrevivem a tudo, formam o mundo real. Esses os filhos de Deus e o objeto de toda a sua solicitude. Os corpos são meros disfarces com que eles aparecem no mundo. Por ocasião das grandes calamidades que dizimam os homens, o espetáculo é semelhante ao de um exército cujos soldados, durante a guerra, ficassem com seus uniformes estragados, rotos, ou perdidos. O general se preocupa mais com seus soldados do que com os uniformes deles." b) — Mas, nem por isso as vítimas desses flagelos deixam de o ser. "Se considerásseis a vida qual ela é e quão pouca coisa representa com relação ao infinito, menos importância lhe daríeis. Em outra vida, essas vítimas acharão ampla compensação aos seus sofrimentos, se souberem suportá-los sem murmurar." Venha por um flagelo a morte, ou por uma causa comum, ninguém deixa por isso de morrer, desde que haja soado a hora da partida. A única diferença, em caso de flagelo, é que maior número parte ao mesmo tempo. Se, pelo pensamento, pudéssemos elevar-nos de maneira a dominar a Humanidade e a abrangê-la em seu conjunto, esses tão terríveis flagelos não nos pareceriam mais do que passageiras tempestades no destino do mundo.', 'rascunho'),
  (739, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Têm os flagelos destruidores utilidade, do ponto de vista físico, não obstante os males que ocasionam?', 'Têm. Muitas vezes mudam as condições de uma região. Mas, o bem que deles resulta só as gerações vindouras o experimentam.', 'rascunho'),
  (740, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Não serão os flagelos, igualmente, provas morais para o homem, por porem-no a braços com as mais aflitivas necessidades?', 'Os flagelos são provas que dão ao homem ocasião de exercitar a sua inteligência, de demonstrar sua paciência e resignação ante a vontade de Deus e que lhe oferecem ensejo de manifestar seus sentimentos de abnegação, de desinteresse e de amor ao próximo, se o não domina o egoísmo.', 'rascunho'),
  (741, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Dado é ao homem conjurar os flagelos que o afligem?', 'Em parte, é; não, porém, como geralmente o entendem. Muitos flagelos resultam da imprevidência do homem. À medida que adquire conhecimentos e experiência, ele os vai podendo conjurar, isto é, prevenir, se lhes sabe pesquisar as causas. Contudo, entre os males que afligem a Humanidade, alguns há de caráter geral, que estão nos decretos da Providência e dos quais cada indivíduo recebe, mais ou menos, o contragolpe. A esses nada pode o homem opor, a não ser sua submissão à vontade de Deus. Esses mesmos males, entretanto, ele muitas vezes os agrava pela sua negligência." Na primeira linha dos flagelos destruidores, naturais e independentes do homem, devem ser colocados a peste, a fome, as inundações, as intempéries fatais às produções da terra. Não tem, porém, o homem encontrado na Ciência, nas obras de arte, no aperfeiçoamento da agricultura, nos afolhamentos e nas irrigações, no estudo das condições higiênicas, meios de impedir, ou, quando menos, de atenuar muitos desastres? Certas regiões, outrora assoladas por terríveis flagelos, não estão hoje preservadas deles? Que não fará, portanto, o homem pelo seu bem-estar material, quando souber aproveitar-se de todos os recursos da sua inteligência e quando, aos cuidados da sua conservação pessoal, souber aliar o sentimento de verdadeira caridade para com os seus semelhantes?', 'rascunho'),
  (742, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Que é o que impele o homem à guerra?', 'Predominância da natureza animal sobre a natureza espiritual e transbordamento das paixões. No estado de barbaria, os povos um só direito conhecem — o do mais forte. Por isso é que, para tais povos, o de guerra é um estado normal. À medida que o homem progride, menos freqüente se torna a guerra, porque ele lhe evita as causas, fazendo-a com humanidade, quando a sente necessária.', 'rascunho'),
  (743, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Da face da Terra, algum dia, a guerra desaparecerá?', 'Sim, quando os homens compreenderem a justiça e praticarem a lei de Deus. Nessa época, todos os povos serão irmãos.', 'rascunho'),
  (744, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Que objetivou a Providência, tornando necessária a guerra?', 'A liberdade e o progresso." a) — Desde que a guerra deve ter por efeito produzir o advento da liberdade, como pode freqüentemente ter por objetivo e resultado a escravização? 242 – Allan Kar dec "Escravização temporária, para esmagar os povos, a fim de fazê-los progredir mais depressa.', 'rascunho'),
  (745, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Que se deve pensar daquele que suscita a guerra para proveito seu?', 'Grande culpado é esse e muitas existências lhe serão necessárias para expiar todos os assassínios de que haja sido causa, porquanto responderá por todos os homens cuja morte tenha causado para satisfazer à sua ambição.', 'rascunho'),
  (746, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'É crime aos olhos de Deus o assassínio?', 'Grande crime, pois que aquele que tira a vida ao seu semelhante corta o fio de uma existência de expiação ou de missão. Aí é que está o mal.', 'rascunho'),
  (747, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'É sempre do mesmo grau a culpabilidade em todos os casos de assassínio?', 'Já o temos dito: Deus é justo, julga mais pela intenção do que pelo fato.', 'rascunho'),
  (748, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Em caso de legítima defesa, escusa Deus o assassínio?', 'Só a necessidade o pode escusar. Mas, desde que o agredido possa preservar sua vida, sem atentar contra a de seu agressor, deve fazê-lo.', 'rascunho'),
  (749, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Tem o homem culpa dos assassínios que pratica durante a guerra?', 'Não, quando constrangido pela força; mas é culpado das crueldades que cometa, sendo-lhe também levado em conta o sentimento de humanidade com que proceda.', 'rascunho'),
  (750, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Qual o mais condenável aos olhos de Deus, o parricídio ou o infanticídio?', 'Ambos o são igualmente, porque todo crime é um crime.', 'rascunho'),
  (751, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Como se explica que entre alguns povos, já adiantados sob o ponto de vista intelectual, o infanticídio seja um costume e esteja consagrado pela legislação?', 'O desenvolvimento intelectual não implica a necessidade do bem. Um Espírito, superior em inteligência, pode ser mau. Isso se dá com aquele que muito tem vivido sem se melhorar: apenas sabe.', 'rascunho'),
  (752, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Poder-se-á ligar o sentimento de crueldade ao instinto de destruição?', 'É o instinto de destruição no que tem de pior, porquanto, se, algumas vezes, a destruição constitui uma necessidade, com a crueldade jamais se dá o mesmo. Ela resulta sempre de uma natureza má.', 'rascunho'),
  (753, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Por que razão a crueldade forma o caráter predominante dos povos primitivos?', 'Nos povos primitivos, como lhes chamas, a matéria prepondera sobre o Espírito. Eles se entregam aos instintos do bruto e, como não experimentam outras necessidades além das da vida do corpo, só da conservação pessoal cogitam e é o que os torna, em geral, cruéis. Demais, os povos de imperfeito desenvolvimento se conservam sob o império de Espíritos também imperfeitos, que lhes são simpáticos, até que povos mais adiantados venham destruir ou enfraquecer essa influência.', 'rascunho'),
  (754, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'A crueldade não derivará da carência de senso moral?', 'Dize — da falta de desenvolvimento do senso moral; não digas da carência, porquanto o senso moral existe, como princípio, em todos os homens. É esse senso moral que dos seres cruéis fará mais tarde seres bons e humanos. Ele, pois, existe no selvagem, mas como o princípio do perfume no gérmen da flor que ainda não desabrochou." Em estado rudimentar ou latente, todas as faculdades existem no homem. Desenvolvem-se, conforme lhes sejam mais ou menos favoráveis as circunstâncias. O desenvolvimento excessivo de umas detém ou neutraliza o das outras. A sobreexcitação dos instintos materiais abafa, por assim dizer, o senso moral, como o desenvolvimento do senso moral enfraquece pouco a pouco as faculdades puramente animais.', 'rascunho'),
  (755, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Como pode dar-se que, no seio da mais adiantada civilização, se encontrem seres às vezes tão cruéis quanto os selvagens?', 'Do mesmo modo que numa árvore carregada de bons frutos se encontram verdadeiros abortos. São, se quiseres, selvagens que da civilização só têm o exterior, lobos extraviados em meio de cordeiros. Espíritos de ordem inferior e muito atrasados podem encarnar entre homens adiantados, na esperança de também se adiantarem. Mas, desde que a prova é por demais pesada, predomina a natureza primitiva.', 'rascunho'),
  (756, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'A sociedade dos homens de bem se verá algum dia expurgada dos seres malfazejos?', 'A Humanidade progride. Esses homens, em quem o instinto do mal domina e que se acham deslocados entre pessoas de bem, desaparecerão gradualmente, como o mau grão se separa do bom, quando este é joeirado. Mas, desaparecerão para renascer sob outros invólucros. Como então terão mais experiência, compreenderão melhor o bem e o mal. Tens disso um exemplo nas plantas e nos animais que o homem há conseguido aperfeiçoar, desenvolvendo neles qualidades novas. Pois bem, só ao cabo de muitas gerações o desenvolvimento se torna completo. É a imagem das diversas existências do homem.', 'rascunho'),
  (757, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Pode-se considerar o duelo como um caso de legítima defesa?', 'Não; é um assassínio e um costume absurdo, digno dos bárbaros. Com uma civilização mais adiantada e mais moral, o homem compreenderá que o duelo é tão ridículo quanto os combates que outrora se consideravam como o juízo de Deus." 244 – Allan Kar dec', 'rascunho'),
  (758, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Poder-se-á considerar o duelo como um assassínio por parte daquele que, conhecendo a sua própria fraqueza, tem a quase certeza de que sucumbirá?', 'É um suicídio." a) — E quando as probabilidades são as mesmas para ambos os duelistas, haverá assassínio ou suicídio? "Um e outro." Em todos os casos, mesmo quando as probabilidades são idênticas para ambos os combatentes, o duelista incorre em culpa, primeiro, porque atenta friamente e de propósito deliberado contra a vida de seu semelhante; depois, porque expõe inutilmente a sua própria vida, sem proveito para ninguém.', 'rascunho'),
  (759, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Que valor tem o que se chama ponto de honra, em matéria de duelo?', 'Orgulho e vaidade: dupla chaga da Humanidade." a) — Mas, não há casos em que a honra se acha verdadeiramente empenhada e em que uma recusa fora covardia? "Isso depende dos usos e costumes. Cada país e cada século tem a esse respeito um modo de ver diferente. Quando os homens forem melhores e estiverem mais adiantados em moral, compreenderão que o verdadeiro ponto de honra está acima das paixões terrenas e que não é matando, nem se deixando matar, que repararão agravos." Há mais grandeza e verdadeira honra em confessar-se culpado o homem, se cometeu alguma falta, ou em perdoar, se de seu lado esteja a razão, e, qualquer que seja o caso, em desprezar os insultos, que o não podem atingir.', 'rascunho'),
  (760, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Desaparecerá algum dia, da legislação humana, a pena de morte?', 'Incontestavelmente desaparecerá e a sua supressão assinalará um progresso da Humanidade. Quando os homens estiverem mais esclarecidos, a pena de morte será completamente abolida na Terra. Não mais precisarão os homens de ser julgados pelos homens. Refiro-me a uma época ainda muito distante de vós." Sem dúvida, o progresso social ainda muito deixa a desejar. Mas, seria injusto para com a sociedade moderna quem não visse um progresso nas restrições postas à pena de morte, no seio dos povos mais adiantados, e à natureza dos crimes a que a sua aplicação se acha limitada. Se compararmos as garantias de que, entre esses mesmos povos, a justiça procura cercar o acusado, a humanidade de que usa para com ele, mesmo quando o reconhece culpado, com o que se praticava em tempos que ainda não vão muito longe, não poderemos negar o avanço do gênero humano na senda do progresso.', 'rascunho'),
  (761, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'A lei de conservação dá ao homem o direito de preservar sua vida. Não usará ele desse direito, quando elimina da sociedade um membro perigoso?', 'Há outros meios de ele se preservar do perigo, que não matando. Demais, é preciso abrir e não fechar ao criminoso a porta do arrependimento.', 'rascunho'),
  (762, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'A pena de morte, que pode vir a ser banida das sociedades civilizadas, não terá sido de necessidade em épocas menos adiantadas?', 'Necessidade não é o termo. O homem julga necessária uma coisa, sempre que não descobre outra melhor. À proporção que se instrui, vai compreendendo melhormente o que é justo e o que é injusto e repudia os excessos cometidos, nos tempos de ignorância, em nome da justiça.', 'rascunho'),
  (763, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Será um indício de progresso da civilização a restrição dos casos em que se aplica a pena de morte?', 'Podes duvidar disso? Não se revolta o teu Espírito, quando lês a narrativa das carnificinas humanas que outrora se faziam em nome da justiça e, não raro, em honra da Divindade; das torturas que se infligiam ao condenado e até ao simples acusado, para lhe arrancar, pela agudeza do sofrimento, a confissão de um crime que muitas vezes não cometera? Pois bem! Se houvesses vivido nessas épocas, terias achado tudo isso natural e talvez mesmo, se foras juiz, fizesses outro tanto. Assim é que o que pareceu justo, numa época, parece bárbaro em outra. Só as leis divinas são eternas; as humanas mudam com o progresso e continuarão a mudar, até que tenham sido postas de acordo com aquelas.', 'rascunho'),
  (764, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Disse Jesus: Quem matou com a espada, pela espada perecerá. Estas palavras não consagram a pena de talião e, assim, a morte dada ao assassino não constitui uma aplicação dessa pena?', 'Tomai cuidado! Muito vos tendes enganado a respeito dessas palavras, como acerca de outras. A pena de talião é a justiça de Deus. É Deus quem a aplica. Todos vós sofreis essa pena a cada instante, pois que sois punidos naquilo em que haveis pecado, nesta existência ou em outra. Aquele que foi causa do sofrimento para seus semelhantes virá a achar-se numa condição em que sofrerá o que tenha feito sofrer. Este o sentido das palavras de Jesus. Mas, não vos disse ele também: Perdoai aos vossos inimigos? E não vos ensinou a pedir a Deus que vos perdoe as ofensas como houverdes vós mesmos perdoado, isto é, na mesma proporção em que houverdes perdoado, compreendei-o bem?', 'rascunho'),
  (765, 'Parte Terceira — Das leis morais', 'Capítulo VI — Da lei de destruição', 'Que se deve pensar da pena de morte imposta em nome de Deus?', 'É tomar o homem o lugar de Deus na distribuição da justiça. Os que assim procedem mostram quão longe estão de compreender Deus e que muito ainda têm que expiar. A pena de morte é um crime, quando aplicada em nome de Deus; e os que a impõem se sobrecarregam de outros tantos assassínios." 246 – Allan Kar dec', 'rascunho'),
  (766, 'Parte Terceira — Das leis morais', 'Capítulo VII — Da lei de sociedade', 'A vida social está em a Natureza?', 'Certamente. Deus fez o homem para viver em sociedade. Não lhe deu inutilmente a palavra e todas as outras faculdades necessárias à vida de relação.', 'rascunho'),
  (767, 'Parte Terceira — Das leis morais', 'Capítulo VII — Da lei de sociedade', 'É contrário à lei da Natureza o insulamento absoluto?', 'Sem dúvida, pois que por instinto os homens buscam a sociedade e todos devem concorrer para progresso, auxiliando-se mutuamente.', 'rascunho'),
  (768, 'Parte Terceira — Das leis morais', 'Capítulo VII — Da lei de sociedade', 'Procurando a sociedade, não fará o homem mais do que obedecer a um sentimento pessoal, ou há nesse sentimento algum providencial objetivo de ordem mais geral?', 'O homem tem que progredir. Insulado, não lhe é isso possível, por não dispor de todas as faculdades. Falta-lhe o contacto com os outros homens. No insulamento, ele se embrutece e estiola." Homem nenhum possui faculdades completas. Mediante a união social é que elas umas às outras se completam, para lhe assegurarem o bem-estar e o progresso. Por isso é que, precisando uns dos outros, os homens foram feitos para viver em sociedade e não insulados.', 'rascunho'),
  (769, 'Parte Terceira — Das leis morais', 'Capítulo VII — Da lei de sociedade', 'Concebe-se que, como princípio geral, a vida social esteja na Natureza. Mas, uma vez que também todos os gostos estão na Natureza, por que será condenável o do insulamento absoluto, desde que cause satisfação ao homem?', 'Satisfação egoísta. Também há homens que experimentam satisfação na embriaguez. Merece-te isso aprovação? Não pode agradar a Deus uma vida pela qual o homem se condena a não ser útil a ninguém.', 'rascunho'),
  (770, 'Parte Terceira — Das leis morais', 'Capítulo VII — Da lei de sociedade', 'Que se deve pensar dos que vivem em absoluta reclusão, fugindo ao pernicioso contacto do mundo?', 'Duplo egoísmo." a) — Mas, não será meritório esse retraimento, se tiver por fim uma expiação, impondo-se aquele que o busca uma privação penosa? "Fazer maior soma de bem do que de mal constitui a melhor expiação. Evitando um mal, aquele que por tal motivo se insula cai noutro, pois esquece a lei de amor e de caridade.', 'rascunho'),
  (771, 'Parte Terceira — Das leis morais', 'Capítulo VII — Da lei de sociedade', 'Que pensar dos que fogem do mundo para se votarem ao mister de socorrer os desgraçados?', 'Esses se elevam, rebaixando-se. Têm o duplo mérito de se colocarem acima dos gozos materiais e de fazerem o bem, obedecendo à lei do trabalho." a) — E dos que buscam no retiro a tranqüilidade que certos trabalhos reclamam? "Isso não é retraimento absoluto do egoísta. Esses não se insulam da sociedade, porquanto para ela trabalham.', 'rascunho'),
  (772, 'Parte Terceira — Das leis morais', 'Capítulo VII — Da lei de sociedade', 'Que pensar do voto de silêncio prescrito por algumas seitas, desde a mais remota antiguidade?', 'Perguntai, antes, a vós mesmos se a palavra é faculdade natural e por que Deus a concedeu ao homem. Deus condena o abuso e não o uso das faculdades que lhe outorgou. Entretanto, o silêncio é útil, pois no silêncio pões em prática o recolhimento; teu espírito se torna mais livre e pode entrar em comunicação conosco. Mas o voto de silêncio é uma tolice. Sem dúvida obedecem a boa intenção os que consideram essas privações como atos de virtude. Enganam-se, no entanto, porque não compreendem suficientemente as verdadeiras leis de Deus." O voto de silêncio absoluto, do mesmo modo que o voto de insulamento, priva o homem das relações sociais que lhe podem facultar ocasiões de fazer o bem e de cumprir a lei do progresso.', 'rascunho'),
  (773, 'Parte Terceira — Das leis morais', 'Capítulo VII — Da lei de sociedade', 'Por que é que, entre os animais, os pais e os filhos deixam de reconhecer-se, desde que estes não mais precisam de cuidados?', 'Os animais vivem vida material e não vida moral. A ternura da mãe pelos filhos tem por princípio o instinto de conservação dos seres que ela deu à luz. Logo que esses seres podem cuidar de si mesmos, está ela com a sua tarefa concluída; nada mais lhe exige a Natureza. Por isso é que os abandona, a fim de se ocupar com os recém-vindos.', 'rascunho'),
  (774, 'Parte Terceira — Das leis morais', 'Capítulo VII — Da lei de sociedade', 'Há pessoas que, do fato de os animais ao cabo de certo tempo abandonarem suas crias, deduzem não serem os laços de família, entre os homens, mais do que 248 – Allan Kar dec resultado dos costumes sociais e não efeito de uma lei da Natureza. Que devemos pensar a esse respeito?', 'Diverso do dos animais é o destino do homem. Por que, então, quererem identificá-lo com estes? Há no homem alguma coisa mais, além das necessidades físicas: há a necessidade de progredir. Os laços sociais são necessários ao progresso e os de família mais apertados tornam os primeiros. Eis por que os segundos constituem uma lei da Natureza. Quis Deus que, por essa forma, os homens aprendessem a amar-se como irmãos.', 'rascunho'),
  (775, 'Parte Terceira — Das leis morais', 'Capítulo VII — Da lei de sociedade', 'Qual seria, para a sociedade, o resultado do relaxamento dos laços de família?', 'Uma recrudescência do egoísmo.', 'rascunho'),
  (776, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Serão coisas idênticas o estado de natureza e a lei natural?', 'Não, o estado de natureza é o estado primitivo. A civilização é incompatível com o estado de natureza, ao passo que a lei natural contribui para o progresso da Humanidade." O estado de natureza é a infância da Humanidade e o ponto de partida do seu desenvolvimento intelectual e moral. Sendo perfectível e trazendo em si o gérmen do seu aperfeiçoamento, o homem não foi destinado a viver perpetuamente no estado de natureza, como não o foi a viver eternamente na infância. Aquele estado é transitório para o homem, que dele sai por virtude do progresso e da civilização. A lei natural, ao contrário, rege a Humanidade inteira e o homem se melhora à medida que melhor a compreende e pratica.', 'rascunho'),
  (777, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Tendo o homem, no estado de natureza, menos necessidades, isento se acha das tribulações que para si mesmo cria, quando num estado de maior adiantamento. Diante disso, que se deve pensar da opinião dos que consideram aquele estado como o da mais perfeita felicidade na Terra?', 'Que queres! é a felicidade do bruto. Há pessoas que não compreendem outra. É ser feliz à maneira dos animais. As crianças também são mais felizes do que os homens feitos.', 'rascunho'),
  (778, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Pode o homem retrogradar para o estado de natureza?', 'Não, o homem tem que progredir incessantemente e não pode volver ao estado de infância. Desde que progride, é porque Deus assim o quer. Pensar que possa retrogradar à sua primitiva condição fora negar a lei do progresso." 250 – Allan Kar dec', 'rascunho'),
  (779, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'A força para progredir, haure-a o homem em si mesmo, ou o progresso é apenas fruto de um ensinamento?', 'O homem se desenvolve por si mesmo, naturalmente. Mas, nem todos progridem simultaneamente e do mesmo modo. Dá-se então que os mais adiantados auxiliam o progresso dos outros, por meio do contacto social.', 'rascunho'),
  (780, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'O progresso moral acompanha sempre o progresso intelectual?', 'Decorre deste, mas nem sempre o segue imediatamente." (l92-365) a) — Como pode o progresso intelectual engendrar o progresso moral? "Fazendo compreensíveis o bem e o mal. O homem, desde então, pode escolher. O desenvolvimento do livre-arbítrio acompanha o da inteligência e aumenta a responsabilidade dos atos." b) — Como é, nesse caso, que, muitas vezes, sucede serem os povos mais instruídos os mais pervertidos também? "O progresso completo constitui o objetivo. Os povos, porém, como os indivíduos, só passo a passo o atingem. Enquanto não se lhes haja desenvolvido o senso moral, pode mesmo acontecer que se sirvam da inteligência para a prática do mal. O moral e a inteligência são duas forças que só com o tempo chegam a equilibrar-se." (365-751)', 'rascunho'),
  (781, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Tem o homem o poder de paralisar a marcha do progresso?', 'Não, mas tem, às vezes, o de embaraçá-la." a) — Que se deve pensar dos que tentam deter a marcha do progresso e fazer que a Humanidade retrograde? "Pobres seres, que Deus castigará! Serão levados de roldão pela torrente que procuram deter." Sendo o progresso uma condição da natureza humana, não está no poder do homem opor-se-lhe. É uma força viva, cuja ação pode ser retardada, porém não anulada, por leis humanas más. Quando estas se tornam incompatíveis com ele, despedaça-as juntamente com os que se esforcem por mantê-las. Assim será, até que o homem tenha posto suas leis em concordância com a justiça divina, que quer que todos participem do bem e não a vigência de leis feitas pelo forte em detrimento do fraco.', 'rascunho'),
  (782, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Não há homens que de boa-fé obstam ao progresso, acreditando favorecê-lo, porque, do ponto de vista em que se colocam, o vêem onde ele não existe?', 'Assemelham-se a pequeninas pedras que, colocadas debaixo da roda de uma grande viatura, não a impedem de avançar.', 'rascunho'),
  (783, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Segue sempre marcha progressiva e lenta o aperfeiçoamento da Humanidade?', 'Há o progresso regular e lento, que resulta da força das coisas. Quando, porém, um povo não progride tão depressa quanto devera, Deus o sujeita, de tempos a tempos, a um abalo físico ou moral que o transforma." O homem não pode conservar-se indefinidamente na ignorância, porque tem de atingir a finalidade que a Providência lhe assinou. Ele se instrui pela força das coisas. As revoluções morais, como as revoluções sociais, se infiltram nas idéias pouco a pouco; germinam durante séculos; depois, irrompem subitamente e produzem o desmoronamento do carunchoso edifício do passado, que deixou de estar em harmonia com as necessidades novas e com as novas aspirações. Nessas comoções, o homem quase nunca percebe senão a desordem e a confusão momentâneas que o ferem nos seus interesses materiais. Aquele, porém, que eleva o pensamento acima da sua própria personalidade, admira os desígnios da Providência, que do mal faz sair o bem. São a procela, a tempestade que saneiam a atmosfera, depois de a terem agitado violentamente.', 'rascunho'),
  (784, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Bastante grande é a perversidade do homem. Não parece que, pelo menos do ponto de vista moral, ele, em vez de avançar, caminha aos recuos?', 'Enganas-te. Observa bem o conjunto e verás que o homem se adianta, pois que melhor compreende o que é mal, e vai dia a dia reprimindo os abusos. Faz-se mister que o mal chegue ao excesso, para tornar compreensível a necessidade do bem e das reformas.', 'rascunho'),
  (785, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Qual o maior obstáculo ao progresso?', 'O orgulho e o egoísmo. Refiro-me ao progresso moral, porquanto o intelectual se efetua sempre. À primeira vista, parece mesmo que o progresso intelectual reduplica a atividade daqueles vícios, desenvolvendo a ambição e o gosto das riquezas, que, a seu turno, incitam o homem a empreender pesquisas que lhe esclarecem o Espírito. Assim é que tudo se prende, no mundo moral, como no mundo físico, e que do próprio mal pode nascer o bem. Curta, porém, é a duração desse estado de coisas, que mudará à proporção que o homem compreender melhor que, além da que o gozo dos bens terrenos proporciona, uma felicidade existe maior e infinitamente mais duradoura." Há duas espécies de progresso, que uma a outra se prestam mútuo apoio, mas que, no entanto, não marcham lado a lado: o progresso intelectual e o progresso moral. Entre os povos civilizados, o primeiro tem recebido, no correr deste século, todos os incentivos. Por isso mesmo atingiu um grau a que ainda não chegara antes da época atual. Muito falta para que o segundo se ache no mesmo nível. Entretanto, comparando-se os costumes sociais de hoje com os de alguns séculos atrás, só um cego negaria o progresso realizado. Ora, sendo assim, por que haveria essa marcha ascendente de parar, com relação, de preferência, ao moral, do que com relação ao intelectual? Por que será impossível que entre o século dezenove e o vigésimo quarto século haja, a esse respeito, tanta diferença quanta entre o décimo quarto século e o século dezenove? Duvidar fora pretender que a Humanidade está no apogeu da perfeição, o que seria absurdo, ou que ela não é perfectível moralmente, o que a experiência desmente.', 'rascunho'),
  (786, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Mostra-nos a História que muitos povos, depois de abalos que os revolveram profundamente, recaíram na barbaria. Onde, neste caso, o progresso? 252 – Allan Kar dec', 'Quando tua casa ameaça ruína, mandas demoli-la e constróis outra mais sólida e mais cômoda. Mas, enquanto esta não se apronta, há perturbação e confusão na tua morada." "Compreende mais o seguinte: eras pobre e habitavas um casebre; tornando-te rico, deixaste-o, para habitar um palácio. Então, um pobre diabo, como eras antes, vem tomar o lugar que ocupavas e fica muito contente, porque estava sem ter onde se abrigar. Pois bem! aprende que os Espíritos que, encarnados, constituem o povo degenerado não são os que o constituíam ao tempo do seu esplendor. Os de então, tendo-se adiantado, passaram para habitações mais perfeitas e progrediram, enquanto os outros, menos adiantados, tomaram o lugar que ficara vago e que também, a seu turno, terão um dia que deixar.', 'rascunho'),
  (787, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Não há raças rebeldes, por sua natureza, ao progresso?', 'Há, mas vão aniquilando-se corporalmente, todos os dias." a) — Qual será a sorte futura das almas que animam essas raças? "Chegarão, como todas as demais, à perfeição, passando por outras existências. Deus a ninguém deserda." b) — Assim, pode dar-se que os homens mais civilizados tenham sido selvagens e antropófagos? "Tu mesmo o foste mais de uma vez, antes de seres o que és.', 'rascunho'),
  (788, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Os povos são individualidades coletivas que como os indivíduos, passam pela infância, pela idade da madureza e pela decrepitude. Esta verdade, que a História comprova, não será de molde a fazer supor que os povos mais adiantados deste século terão seu declínio e sua extinção, como os da antiguidade?', 'Os povos, que apenas vivem a vida do corpo, aqueles cuja grandeza unicamente assenta na força e na extensão territorial, nascem, crescem e morrem, porque a força de um povo se exaure, como a de um homem. Aqueles, cujas leis egoísticas obstam ao progresso das luzes e da caridade, morrem, porque a luz mata as trevas e a caridade mata o egoísmo. Mas, para os povos, como para os indivíduos, há a vida da alma. Aqueles, cujas leis se harmonizam com as leis eternas do Criador, viverão e servirão de farol aos outros povos.', 'rascunho'),
  (789, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'O progresso fará que todos os povos da Terra se achem um dia reunidos, formando uma só nação?', 'Uma nação única, não; seria impossível, visto que da diversidade dos climas se originam costumes e necessidades diferentes, que constituem as nacionalidades, tornando indispensáveis sempre leis apropriadas a esses costumes e necessidades. A caridade, porém, desconhece latitudes e não distingue a cor dos homens. Quando, por toda parte, a lei de Deus servir de base à lei humana, os povos praticarão entre si a caridade, como os indivíduos. Então, viverão felizes e em paz, porque nenhum cuidará de causar dano ao seu vizinho, nem de viver a expensas dele." A Humanidade progride, por meio dos indivíduos que pouco a pouco se melhoram e instruem. Quando estes preponderam pelo número, tomam a dianteira e arrastam os outros. De tempos a tempos, surgem no seio dela homens de gênio que lhe dão um impulso; vêm depois, como instrumentos de Deus, os que têm autoridade e, nalguns anos, fazem-na adiantar-se de muitos séculos. O progresso dos povos também realça a justiça da reencarnação. Louváveis esforços empregam os homens de bem para conseguir que uma nação se adiante, moral e intelectualmente. Transformada, a nação será mais ditosa neste mundo e no outro, concebe- se. Mas, durante a sua marcha lenta através dos séculos, milhares de indivíduos morrem todos os dias. Qual a sorte de todos os que sucumbem ao longo do trajeto? Privá-los-á, a sua relativa inferioridade, da felicidade reservada aos que chegam por último? Ou também relativa será a felicidade que lhes cabe? Não é possível que a justiça divina haja consagrado semelhante injustiça. Com a pluralidade das existências, é igual para todos o direito à felicidade, porque ninguém fica privado do progresso. Podendo, os que viveram ao tempo da barbaria, voltar, na época da civilização, a viver no seio do mesmo povo, ou de outro, é claro que todos tiram proveito da marcha ascensional. Outra dificuldade, no entanto, apresenta aqui o sistema da unicidade das existências. Segundo este sistema, a alma é criada no momento em que nasce o ser humano. Então, se um homem é mais adiantado do que outro, é que Deus criou para ele uma alma mais adiantada. Por que esse favor? Que merecimento tem esse homem, que não viveu mais do que outro, que talvez haja vivido menos, para ser dotado de uma alma superior? Esta, porém, não é a dificuldade principal. Se os homens vivessem um milênio, conceber-se-ia que, nesse período milenar, tivessem tempo de progredir. Mas, diariamente morrem criaturas em todas as idades; incessantemente se renovam na face do planeta, de tal sorte que todos os dias aparece uma multidão delas e outra desaparece. Ao cabo de mil anos, já não há naquela nação vestígio de seus antigos habitantes. Contudo, de bárbara, que era, ela se tornou policiada. Que foi o que progrediu? Foram os indivíduos outrora bárbaros? Mas, esses morreram há muito tempo. Teriam sido os recém-chegados? Mas, se suas almas foram criadas no momento em que eles nasceram, essas almas não existiam na época da barbaria e forçoso será então admitir-se que os esforços que se despendem para civilizar um povo têm o poder, não de melhorar almas imperfeitas, porém de fazer que Deus crie almas mais perfeitas. Comparemos esta teoria do progresso com a que os Espíritos apresentaram. As almas vindas no tempo da civilização tiveram sua infância, como todas as outras, mas já tinham vivido antes e vêm adiantadas por efeito do progresso realizado anteriormente. Vêm atraídas por um meio que lhes é simpático e que se acha em relação com o estado em que atualmente se encontram. De sorte que, os cuidados dispensados à civilização de um povo não têm como conseqüência fazer que, de futuro, se criem almas mais perfeitas; têm, sim, o de atrair as que já progrediram, quer tenham vivido no seio do povo que se figura, ao tempo da sua barbaria, quer venham de outra parte. Aqui se nos depara igualmente a chave do progresso da Humanidade inteira. Quando todos os povos estiverem no mesmo nível, no tocante ao sentimento do bem, a Terra será ponto de reunião exclusivamente de bons Espíritos, que viverão fraternalmente unidos. Os maus, sentindo-se aí repelidos e deslocados, irão procurar, em mundos inferiores, o meio que lhes convém, até que sejam dignos de volver ao nosso, então transformado. Da teoria vulgar ainda resulta que os trabalhos de melhoria social só às gerações presentes e futuras aproveitam, sendo de resultados nulos para as gerações passadas, que cometeram o erro de vir muito cedo e que ficam sendo o que podem ser, sobrecarregadas com o peso de seus atos de barbaria. Segundo a doutrina dos Espíritos, os progressos ulteriores aproveitam igualmente às gerações pretéritas, que voltam a viver em melhores condições e podem assim aperfeiçoar-se no foco da civilização. 254 – Allan Kar dec', 'rascunho'),
  (790, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'É um progresso a civilização ou, como o entendem alguns filósofos, uma decadência da Humanidade?', 'Progresso incompleto. O homem não passa subitamente da infância à madureza." a) — Será racional condenar-se a civilização? "Condenai antes os que dela abusam e não a obra de Deus.', 'rascunho'),
  (791, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Apurar-se-á algum dia a civilização, de modo a fazer que desapareçam os males que haja produzido?', 'Sim, quando o moral estiver tão desenvolvido quanto à inteligência. O fruto não pode surgir antes da flor.', 'rascunho'),
  (792, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Por que não efetua a civilização, imediatamente, todo o bem que poderia produzir?', 'Porque os homens ainda não estão aptos nem dispostos a alcançá-lo." a) — Não será também porque, criando novas necessidades, suscita paixões novas? "É, e ainda porque não progridem simultaneamente todas as faculdades do Espírito. Tempo é preciso para tudo. De uma civilização incompleta não podeis esperar frutos perfeitos." (751-780)', 'rascunho'),
  (793, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Por que indícios se pode reconhecer uma civilização completa?', 'Reconhecê-la-eis pelo desenvolvimento moral. Credes que estais muito adiantados, porque tendes feito grandes descobertas e obtido maravilhosas invenções; porque vos alojais e vestis melhor do que os selvagens. Todavia, não tereis verdadeiramente o direito de dizer-vos civilizados, senão quando de vossa sociedade houverdes banido os vícios que a desonram e quando viverdes como irmãos, praticando a caridade cristã. Até então, sereis apenas povos esclarecidos, que hão percorrido a primeira fase da civilização." A civilização, como todas as coisas, apresenta gradações diversas. Uma civilização incompleta é um estado transitório, que gera males especiais, desconhecidos do homem no estado primitivo. Nem por isso, entretanto, constitui menos um progresso natural, necessário, que traz consigo o remédio para o mal que causa. À medida que a civilização se aperfeiçoa, faz cessar alguns dos males que gerou, males que desaparecerão todos com o progresso moral. De duas nações que tenham chegado ao ápice da escala social, somente pode considerar-se a mais civilizada, na legítima acepção do termo, aquela onde exista menos egoísmo, menos cobiça e menos orgulho; onde os hábitos sejam mais intelectuais e morais do que materiais; onde a inteligência se puder desenvolver com maior liberdade; onde haja mais bondade, boa-fé, benevolência e generosidade recíprocas; onde menos enraizados se mostrem os preconceitos de casta e de nascimento, por isso que tais preconceitos são incompatíveis com o verdadeiro amor do próximo; onde as leis nenhum privilégio consagrem e sejam as mesmas, assim para o último, como para o primeiro; onde com menos parcialidade se exerça a justiça; onde o fraco encontre sempre amparo contra o forte; onde a vida do homem, suas crenças e opiniões sejam melhormente respeitadas; onde exista menor número de desgraçados; enfim, onde todo homem de boa vontade esteja certo de lhe não faltar o necessário.', 'rascunho'),
  (794, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Poderia a sociedade reger-se unicamente pelas leis naturais, sem o concurso das leis humanas?', 'Poderia, se todos as compreendessem bem. Se os homens as quisessem praticar, elas bastariam. A sociedade, porém, tem suas exigências. São-lhe necessárias leis especiais.', 'rascunho'),
  (795, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Qual a causa da instabilidade das leis humanas?', 'Nas épocas de barbaria, são os mais fortes que fazem as leis e eles as fizeram para si. À proporção que os homens foram compreendendo melhor a justiça, indispensável se tornou a modificação delas. Quanto mais se aproximam da vera justiça, tanto menos instáveis são as leis humanas, isto é, tanto mais estáveis se vão tornando, conforme vão sendo feitas para todos e se identificam com a lei natural." A civilização criou necessidades novas para o homem, necessidades relativas à posição social que ele ocupe. Tem-se então que regular, por meio de leis humanas, os direitos e deveres dessa posição. Mas, influenciado pelas suas paixões, ele não raro há criado direitos e deveres imaginários, que a lei natural condena e que os povos riscam de seus códigos à medida que progridem. A lei natural é imutável e a mesma para todos; a lei humana é variável e progressiva. Na infância das sociedades, esta só pôde consagrar o direito do mais forte.', 'rascunho'),
  (796, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'No estado atual da sociedade, a severidade das leis penais não constitui uma necessidade?', 'Uma sociedade depravada certamente precisa de leis severas. Infelizmente, essas leis mais se destinam a punir o mal depois de feito, do que a lhe secar a fonte. Só a educação poderá reformar os homens, que, então, não precisarão mais de leis tão rigorosas.', 'rascunho'),
  (797, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Como poderá o homem ser levado a reformar suas leis?', 'Isso ocorre naturalmente, pela força mesma das coisas e da influência das pessoas que o guiam na senda do progresso. Muitas já ele reformou e muitas outras reformará. Espera!', 'rascunho'),
  (798, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'O Espiritismo se tornará crença comum, ou ficará sendo partilhado, como crença, apenas por algumas pessoas?', 'Certamente que se tornará crença geral e marcará nova era na história da humanidade, porque está na natureza e chegou o tempo em que ocupará lugar entre os conhecimentos humanos. Terá, no entanto, que sustentar grandes lutas, mais 256 – Allan Kar dec contra o interesse, do que contra a convicção, porquanto não há como dissimular a existência de pessoas interessadas em combatê-lo, umas por amor-próprio, outras por causas inteiramente materiais. Porém, como virão a ficar insulados, seus contraditores se sentirão forçados a pensar como os demais, sob pena de se tornarem ridículos." As idéias só com o tempo se transformam; nunca de súbito. De geração em geração, elas se enfraquecem e acabam por desaparecer, paulatinamente, com os que as professavam, os quais vêm a ser substituídos por outros indivíduos imbuídos de novos princípios, como sucede com as idéias políticas. Vede o paganismo. Não há hoje mais quem professe as idéias religiosas dos tempos pagãos. Todavia, muitos séculos após o advento do Cristianismo, delas ainda restavam vestígios, que somente a completa renovação das raças conseguiu apagar. Assim será com o Espiritismo. Ele progride muito; mas, durante duas ou três gerações, ainda haverá um fermento de incredulidade, que unicamente o tempo aniquilará. Sua marcha, porém, será mais célere que a do Cristianismo, porque o próprio Cristianismo é quem lhe abre o caminho e serve de apoio. O Cristianismo tinha que destruir; o Espiritismo só tem que edificar.', 'rascunho'),
  (799, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'De que maneira pode o Espiritismo contribuir para o progresso?', 'Destruindo o materialismo, que é uma das chagas da sociedade, ele faz que os homens compreendam onde se encontram seus verdadeiros interesses. Deixando a vida futura de estar velada pela dúvida, o homem perceberá melhor que, por meio do presente, lhe é dado preparar o seu futuro. Abolindo os prejuízos de seitas, castas e cores, ensina aos homens a grande solidariedade que os há de unir como irmãos.', 'rascunho'),
  (800, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Não será de temer que o Espiritismo não consiga triunfar da negligência dos homens e do seu apego às coisas materiais?', 'Conhece bem pouco os homens quem imagine que uma causa qualquer os possa transformar como que por encanto. As idéias só pouco a pouco se modificam, conforme os indivíduos, e preciso é que algumas gerações passem, para que se apaguem totalmente os vestígios dos velhos hábitos. A transformação, pois, somente com o tempo, gradual e progressivamente, se pode operar. Para cada geração uma parte do véu se dissipa. O Espiritismo vem rasgá-lo de alto a baixo. Entretanto, conseguisse ele unicamente corrigir num homem um único defeito que fosse e já o haveria forçado a dar um passo. Ter-lhe-ia feito, só com isso, grande bem, pois esse primeiro passo lhe facilitará os outros.', 'rascunho'),
  (801, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Por que não ensinaram os Espíritos, em todos os tempos, o que ensinam hoje?', 'Não ensinais às crianças o que ensinais aos adultos e não dais ao recém- nascido um alimento que ele não possa digerir. Cada coisa tem seu tempo. Eles ensinaram muitas coisas que os homens não compreenderam ou adulteraram, mas que podem compreender agora. Com seus ensinos, embora incompletos, prepararam o terreno para receber a semente que vai frutificar.', 'rascunho'),
  (802, 'Parte Terceira — Das leis morais', 'Capítulo VIII — Da lei do progresso', 'Visto que o Espiritismo tem que marcar um progresso da Humanidade, por que não apressam os Espíritos esse progresso, por meio de manifestações tão generalizadas e patentes, que a convicção penetre até nos mais incrédulos?', 'Desejaríeis milagres; mas, Deus os espalha a mancheias diante dos vossos passos e, no entanto, ainda há homens que o negam. Conseguiu, porventura, o próprio Cristo convencer os seus contemporâneos, mediante os prodígios que operou? Não conheceis presentemente alguns que negam os fatos mais patentes, ocorridos às suas vistas? Não há os que dizem que não acreditariam, mesmo que vissem? Não; não é por meio de prodígios que Deus quer encaminhar os homens. Em sua bondade, ele lhes deixa o mérito de se convencerem pela razão." 258 – Allan Kar dec', 'rascunho'),
  (803, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Perante Deus, são iguais todos os homens?', 'Sim, todos tendem para o mesmo fim e Deus fez suas leis para todos. Dizeis freqüentemente: ‘O Sol luz para todos’ e enunciais assim uma verdade maior e mais geral do que pensais." Todos os homens estão submetidos às mesmas leis da Natureza. Todos nascem igualmente fracos, acham-se sujeitos às mesmas dores e o corpo do rico se destrói como o do pobre. Deus a nenhum homem concedeu superioridade natural, nem pelo nascimento, nem pela morte: todos, aos seus olhos, são iguais.', 'rascunho'),
  (804, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Por que não outorgou Deus as mesmas aptidões a todos os homens?', 'Deus criou iguais todos os Espíritos, mas cada um destes vive há mais ou menos tempo, e, conseguintemente, tem feito maior ou menor soma de aquisições. A diferença entre eles está na diversidade dos graus da experiência alcançada e da vontade com que obram, vontade que é o livre-arbítrio. Daí o se aperfeiçoarem uns mais rapidamente do que outros, o que lhes dá aptidões diversas. Necessária é a variedade das aptidões, a fim de que cada um possa concorrer para a execução dos desígnios da Providência, no limite do desenvolvimento de suas forças físicas e intelectuais. O que um não faz, fá-lo outro. Assim é que cada qual tem seu papel útil a desempenhar. Demais, sendo solidários entre si todos os mundos, necessário se torna que os habitantes dos mundos superiores, que, na sua maioria, foram criados antes do vosso, venham habitá-lo, para vos dar o exemplo.', 'rascunho'),
  (805, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Passando de um mundo superior a outro inferior, conserva o Espírito, integralmente, as faculdades adquiridas?', 'Sim, já temos dito que o Espírito que progrediu não retrocede. Poderá escolher, no estado de Espírito livre, um invólucro mais grosseiro, ou posição mais precária do que as que já teve, porém tudo isso para lhe servir de ensinamento e ajudá-lo a progredir." Assim, a diversidade das aptidões entre os homens não deriva da natureza íntima da sua criação, mas do grau de aperfeiçoamento a que tenham chegado os Espíritos encarnados neles. Deus, portanto, não criou faculdades desiguais; permitiu, porém, que os Espíritos em graus diversos de desenvolvimento estivessem em contacto, para que os mais adiantados pudessem auxiliar o progresso dos mais atrasados e também para que os homens, necessitando uns dos outros, compreendessem a lei de caridade que os deve unir.', 'rascunho'),
  (806, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'É lei da natureza a desigualdade das condições sociais?', 'Não; é obra do homem e não de Deus." a) — Algum dia essa desigualdade desaparecerá? "Eternas somente as leis de Deus o são. Não vês que dia a dia ela gradualmente se apaga? Desaparecerá quando o egoísmo e o orgulho deixarem de predominar. Restará apenas a desigualdade do merecimento. Dia virá em que os membros da grande família dos filhos de Deus deixarão de considerar-se como de sangue mais ou menos puro. Só o Espírito é mais ou menos puro e isso não depende da posição social.', 'rascunho'),
  (807, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Que se deve pensar dos que abusam da superioridade de suas posições sociais, para, em proveito próprio, oprimir os fracos?', 'Merecem anátema! Ai deles! Serão, a seu turno, oprimidos: renascerão numa existência em que terão de sofrer tudo o que tiverem feito sofrer aos outros.', 'rascunho'),
  (808, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'A desigualdade das riquezas não se originará da das faculdades, em virtude da qual uns dispõem de mais meios de adquirir bens do que outros?', 'Sim e não. Da velhacaria e do roubo, que dizes?" a) — Mas, a riqueza herdada, essa não é fruto de paixões más. "Que sabes a esse respeito? Busca a fonte de tal riqueza e verás que nem sempre é pura. Sabes, porventura, se não se originou de uma espoliação ou de uma injustiça? Mesmo, porém, sem falar da origem, que pode ser má, acreditas que a 260 – Allan Kar dec cobiça da riqueza, ainda quando bem adquirida, os desejos secretos de possuí-la o mais depressa possível, sejam sentimentos louváveis? Isso o que Deus julga e eu te asseguro que o seu juízo é mais severo que o dos homens.', 'rascunho'),
  (809, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Aos que, mais tarde, herdam uma riqueza inicialmente mal adquirida, alguma responsabilidade cabe por esse fato?', 'É fora de dúvida que não são responsáveis pelo mal que outros hajam feito, sobretudo se o ignoram, como é possível que aconteça. Mas, fica sabendo que, muitas vezes, a riqueza só vem ter às mãos de um homem, para lhe proporcionar ensejo de reparar uma injustiça. Feliz dele, se assim o compreende! Se a fizer em nome daquele que cometeu a injustiça, a ambos será a reparação levada em conta, porquanto, não raro, é este último quem a provoca.', 'rascunho'),
  (810, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Sem quebra da legalidade, quem quer que seja pode dispor de seus bens de modo mais ou menos eqüitativo. Aquele que assim proceder será responsável, depois da morte, pelas disposições que haja tomado?', 'Toda ação produz seus frutos; doces são os das boas ações, amargos sempre os das outras. Sempre, entendei-o bem.', 'rascunho'),
  (811, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Será possível e já terá existido a igualdade absoluta das riquezas?', 'Não; nem é possível. A isso se opõe a diversidade das faculdades e dos caracteres." a) — Há, no entanto, homens que julgam ser esse o remédio aos males da sociedade. Que pensais a respeito? "São sistemáticos esses tais, ou ambiciosos cheios de inveja. Não compreendem que a igualdade com que sonham seria a curto prazo desfeita pela força das coisas. Combatei o egoísmo, que é a vossa chaga social, e não corrais atrás de quimeras.', 'rascunho'),
  (812, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Por não ser possível a igualdade das riquezas, o mesmo se dará com o bem- estar?', 'Não, mas o bem-estar é relativo e todos poderiam dele gozar, se se entendessem convenientemente, porque o verdadeiro bem-estar consiste em cada um empregar o seu tempo como lhe apraza e não na execução de trabalhos pelos quais nenhum gosto sente. Como cada um tem aptidões diferentes, nenhum trabalho útil ficaria por fazer. Em tudo existe o equilíbrio; o homem é quem o perturba." a) — Será possível que todos se entendam? "Os homens se entenderão quando praticarem a lei de justiça.', 'rascunho'),
  (813, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Há pessoas que, por culpa sua, caem na miséria. Nenhuma responsabilidade caberá disso à sociedade?', 'Mas, certamente. Já dissemos que a sociedade é muitas vezes a principal culpada de semelhante coisa. De mais, não tem ela que velar pela educação moral dos seus membros? Quase sempre, é a má-educação que lhes falseia o critério, ao invés de sufocar-lhes as tendências perniciosas.', 'rascunho'),
  (814, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Por que Deus a uns concedeu as riquezas e o poder, e a outros, a miséria?', 'Para experimentá-los de modos diferentes. Além disso, como sabeis, essas provas foram escolhidas pelos próprios Espíritos, que nelas, entretanto, sucumbem com freqüência.', 'rascunho'),
  (815, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Qual das duas provas é mais terrível para o homem, a da desgraça ou a da riqueza?', 'São-no tanto uma quanto outra. A miséria provoca as queixas contra a Providência, a riqueza incita a todos os excessos.', 'rascunho'),
  (816, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Estando o rico sujeito a maiores tentações, também não dispõe, por outro lado, de mais meios de fazer o bem?', 'Mas, é justamente o que nem sempre faz. Torna-se egoísta, orgulhoso e insaciável. Com a riqueza, suas necessidades aumentam e ele nunca julga possuir o bastante para si unicamente." A alta posição do homem neste mundo e o ter autoridade sobre os seus semelhantes são provas tão grandes e tão escorregadias como a desgraça, porque, quanto mais rico e poderoso é ele, tanto mais obrigações tem que cumprir e tanto mais abundantes são os meios de que dispõe para fazer o bem e o mal. Deus experimenta o pobre pela resignação e o rico pelo emprego que dá aos seus bens e ao seu poder. A riqueza e o poder fazem nascer todas as paixões que nos prendem à matéria e nos afastam da perfeição espiritual. Por isso foi que Jesus disse: " Em verdade vos digo que mais fácil é passar um camelo por um fundo de agulha do que entrar um rico no reino dos céus.', 'rascunho'),
  (817, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'São iguais perante Deus o homem e a mulher e têm os mesmos direitos?', 'Não outorgou Deus a ambos a inteligência do bem e do mal e a faculdade de progredir?', 'rascunho'),
  (818, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Donde provém a inferioridade moral da mulher em certos países?', 'Do predomínio injusto e cruel que sobre ela assumiu o homem. É resultado das instituições sociais e do abuso da força sobre a fraqueza. Entre homens moralmente pouco adiantados, a força faz o direito.', 'rascunho'),
  (819, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Com que fim mais fraca fisicamente do que o homem é a mulher?', 'Para lhe determinar funções especiais. Ao homem, por ser o mais forte, os trabalhos rudes; à mulher, os trabalhos leves; a ambos o dever de se ajudarem mutuamente a suportar as provas de uma vida cheia de amargor.', 'rascunho'),
  (820, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'A fraqueza física da mulher não a coloca naturalmente sob a dependência do homem? 262 – Allan Kar dec', 'Deus a uns deu a força, para protegerem o fraco e não para o escravizarem." Deus apropriou a organização de cada ser às funções que lhe cumpre desempenhar. Tendo dado à mulher menor força física, deu-lhe ao mesmo tempo maior sensibilidade, em relação com a delicadeza das funções maternais e com a fraqueza dos seres confiados aos seus cuidados.', 'rascunho'),
  (821, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'As funções a que a mulher é destinada pela Natureza terão importância tão grande quanto as deferidas ao homem?', 'Sim, maior até. É ela quem lhe dá as primeiras noções da vida.', 'rascunho'),
  (822, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Sendo iguais perante a lei de Deus, devem os homens ser iguais também perante as leis humanas?', 'O primeiro princípio de justiça é este: Não façais aos outros o que não quereríeis que vos fizessem." a) — Assim sendo, uma legislação, para ser perfeitamente justa, deve consagrar a igualdade dos direitos do homem e da mulher? "Dos direitos, sim; das funções, não. Preciso é que cada um esteja no lugar que lhe compete. Ocupe-se do exterior o homem e do interior a mulher, cada um de acordo com a sua aptidão. A lei humana, para ser eqüitativa, deve consagrar a igualdade dos direitos do homem e da mulher. Todo privilégio a um ou a outro concedido é contrário à justiça. A emancipação da mulher acompanha o progresso da civilização. Sua escravização marcha de par com a barbaria. Os sexos, além disso, só existem na organização física. Visto que os Espíritos podem encarnar num e noutro, sob esse aspecto nenhuma diferença há entre eles. Devem, por conseguinte, gozar dos mesmos direitos.', 'rascunho'),
  (823, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Donde nasce o desejo que o homem sente de perpetuar sua memória por meio de monumentos fúnebres?', 'Último ato de orgulho." a) — Mas a suntuosidade dos monumentos fúnebres não é antes devida, as mais das vezes, aos parentes do defunto, que lhe querem honrar a memória, do que ao próprio defunto? "Orgulho dos parentes, desejosos de se glorificarem a si mesmos. Oh! sim, nem sempre é pelo morto que se fazem todas essas demonstrações. Elas são feitas por amor-próprio e para o mundo, bem como por ostentação de riqueza. Supões, porventura, que a lembrança de um ser querido dure menos no coração do pobre, que não lhe pode colocar sobre o túmulo senão uma singela flor? Supões que o mármore salva do esquecimento aquele que na Terra foi inútil?', 'rascunho'),
  (824, 'Parte Terceira — Das leis morais', 'Capítulo IX — Da lei de igualdade', 'Reprovais então, de modo absoluto, a pompa dos funerais?', 'Não; quando se tenha em vista honrar a memória de um homem de bem, é justo e de bom exemplo." O túmulo é o ponto de reunião de todos os homens. Aí terminam inelutavelmente todas as distinções humanas. Em vão tenta o rico perpetuar a sua memória, mandando erigir faustosos monumentos. O tempo os destruirá, como lhe consumirá o corpo. Assim o quer a Natureza. Menos perecível do que o seu túmulo será a lembrança de suas ações boas e más. A pompa dos funerais não o limpará das suas torpezas, nem o fará subir um degrau que seja na hierarquia espiritual. (320 e seguintes) 264 – Allan Kar dec', 'rascunho'),
  (825, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Haverá no mundo posições em que o homem possa jactar-se de gozar de absoluta liberdade?', 'Não, porque todos precisais uns dos outros, assim os pequenos como os grandes.', 'rascunho'),
  (826, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Em que condições poderia o homem gozar de absoluta liberdade?', 'Nas do eremita no deserto. Desde que juntos estejam dois homens, há entre eles direitos recíprocos que lhes cumpre respeitar; não mais, portanto, qualquer deles goza de liberdade absoluta.', 'rascunho'),
  (827, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'A obrigação de respeitar os direitos alheios tira ao homem o de pertencer-se a si mesmo?', 'De modo algum, porquanto este é um direito que lhe vem da natureza.', 'rascunho'),
  (828, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Como se podem conciliar as opiniões liberais de certos homens com o despotismo que costumam exercer no seu lar e sobre os seus subordinados?', 'Eles têm a compreensão da lei natural, mas contrabalançada pelo orgulho e pelo egoísmo. Quando não representam calculadamente uma comédia, sustentando princípios liberais, compreendem como as coisas devem ser, mas não as fazem assim." a) — Ser-lhes-ão, na outra vida, levados em conta os princípios que professaram neste mundo? "Quanto mais inteligência tem o homem para compreender um princípio, tanto menos escusável é de o não aplicar a si mesmo. Em verdade vos digo que o homem simples, porém sincero, está mais adiantado no caminho de Deus, do que um que pretenda parecer o que não é.', 'rascunho'),
  (829, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Haverá homens que estejam, por natureza, destinados a ser propriedades de outros homens?', 'É contrária à lei de Deus toda sujeição absoluta de um homem a outro homem. A escravidão é um abuso da força. Desaparece com o progresso, como gradativamente desaparecerão todos os abusos." É contrária à Natureza a lei humana que consagra a escravidão, pois que assemelha o homem ao irracional e o degrada física e moralmente.', 'rascunho'),
  (830, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Quando a escravidão faz parte dos costumes de um povo, são censuráveis os que dela aproveitam, embora só o façam conformando-se com um uso que lhes parece natural?', 'O mal é sempre o mal e não há sofisma que faça se torne boa uma ação má. A responsabilidade, porém, do mal é relativa aos meios de que o homem disponha para compreendê-lo. Aquele que tira proveito da lei da escravidão é sempre culpado de violação da lei da Natureza. Mas, aí, como em tudo, a culpabilidade é relativa. Tendo-se a escravidão introduzido nos costumes de certos povos, possível se tornou que, de boa-fé, o homem se aproveitasse dela como de uma coisa que lhe parecia natural. Entretanto, desde que, mais desenvolvida e, sobretudo, esclarecida pelas luzes do Cristianismo, sua razão lhe mostrou que o escravo era um seu igual perante Deus, nenhuma desculpa mais ele tem.', 'rascunho'),
  (831, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'A desigualdade natural das aptidões não coloca certas raças humanas sob a dependência das raças mais inteligentes?', 'Sim, mas para que estas as elevem, não para embrutecê-las ainda mais pela escravização. Durante longo tempo, os homens consideram certas raças humanas como animais de trabalho, munidos de braços e mãos, e se julgaram com o direito de vender os dessas raças como bestas de carga. Consideram-se de sangue mais puro os que assim procedem. Insensatos! nada vêem senão a matéria. Mais ou menos puro não é o sangue, porém o Espírito." (361-803)', 'rascunho'),
  (832, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Há, no entanto, homens que tratam seus escravos com humanidade; que não deixam lhes falte nada e acreditam que a liberdade os exporia a maiores privações. Que dizeis disso?', 'Digo que esses compreendem melhor os seus interesses. Igual cuidado dispensam aos seus bois e cavalos, para que obtenham bom preço no mercado. Não 266 – Allan Kar dec são tão culpados como os que maltratam os escravos, mas, nem por isso deixam de dispor deles como de uma mercadoria, privando-os do direito de se pertencerem a si mesmos.', 'rascunho'),
  (833, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Haverá no homem alguma coisa que escape a todo constrangimento e pela qual goze ele de absoluta liberdade?', 'No pensamento goza o homem de ilimitada liberdade, pois que não há como pôr-lhe peias. Pode-se-lhe deter o vôo, porém, não aniquilá-lo.', 'rascunho'),
  (834, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'É responsável o homem pelo seu pensamento?', 'Perante Deus, é. Somente a Deus sendo possível conhecê-lo, ele o condena ou absolve, segundo a sua justiça.', 'rascunho'),
  (835, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Será a liberdade de consciência uma conseqüência da de pensar?', 'A consciência é um pensamento íntimo, que pertence ao homem, como todos os outros pensamentos.', 'rascunho'),
  (836, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Tem o homem direito de pôr embaraços à liberdade de consciência?', 'Falece-lhe tanto esse direito, quanto com referência à liberdade de pensar, por isso que só a Deus cabe o de julgar a consciência. Assim como os homens, pelas suas leis, regulam as relações de homem para homem, Deus, pelas leis da natureza, regula as relações entre ele e o homem.', 'rascunho'),
  (837, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Que é o que resulta dos embaraços que se oponham à liberdade de consciência?', 'Constranger os homens a procederem em desacordo com o seu modo de pensar, fazê-los hipócritas. A liberdade de consciência é um dos caracteres da verdadeira civilização e do progresso.', 'rascunho'),
  (838, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Será respeitável toda e qualquer crença, ainda quando notoriamente falsa?', 'Toda crença é respeitável, quando sincera e conducente à prática do bem. Condenáveis são as crenças que conduzam ao mal.', 'rascunho'),
  (839, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Será repreensível aquele que escandalize com a sua crença um outro que não pensa como ele?', 'Isso é faltar com a caridade e atentar contra a liberdade de pensamento.', 'rascunho'),
  (840, 'Parte Terceira — Das leis morais', 'Capítulo X — Da lei de liberdade', 'Será atentar contra a liberdade de consciência pôr óbices a crenças capazes de causar perturbações à sociedade?', 'Podem reprimir-se os atos, mas a crença íntima é inacessível." Reprimir os atos exteriores de uma crença, quando acarretam qualquer prejuízo a terceiros, não é atentar contra a liberdade de consciência, pois que essa repressão em nada tira à crença a liberdade, que ela conserva integral.', 'rascunho')
